type Product = {
  id: string; name: string; category: string; seller: string; sellerVerified: boolean;
  price: number; unit: string; thc: number; cbd: number; rating: number;
  reviewCount: number; image: string; stockStatus: 'In stock' | 'Low stock' | 'Sold out';
};
type Seller = {
  id: string; name: string; location: string; licenseStatus: 'Verified' | 'Pending' | 'Needs review';
  licenseNumber: string; rating: number; productCount: number; lastActive: string;
};
type Order = {
  id: string; seller: string; items: string[]; total: number; status: 'New' | 'Preparing' | 'Ready' | 'Completed';
  createdAt: string; pickupWindow: string;
};
type Activity = { id: string; type: string; title: string; description: string; timestamp: string; status: 'good' | 'attention' | 'neutral' };
type Post = {
  id: string; author: string; handle: string; avatar: string; createdAt: string; body: string;
  type: 'Discussion' | 'Strain note' | 'Local activity'; locationLabel: string; tags: string[];
  likes: number; comments: number; saved: boolean; verifiedAuthor: boolean;
};
type Comment = { id: string; postId: string; author: string; body: string; createdAt: string };
type NearbyPlace = {
  id: string; name: string; kind: 'Dispensary' | 'Pickup point'; distance: string; address: string;
  openNow: boolean; verified: boolean; products: number; coordinates: { lat: number; lng: number };
};
type Conversation = {
  id: string; kind: 'seller' | 'friend'; participantName: string; participantHandle: string;
  participantVerified: boolean; avatar: string; lastMessage: string; lastMessageAt: string;
  unreadCount: number; contextLabel: string; onlineStatus: 'online' | 'away' | 'offline';
};
type Message = {
  id: string; conversationId: string; senderId: string; senderName: string; body: string;
  sentAt: string; isMine: boolean; status: 'sent' | 'delivered' | 'read';
};
type StorePlan = {
  id: string; name: string; monthlyPrice: number; listingLimit: number | null;
  featured: boolean; description: string; status: 'available' | 'active' | 'cancelled';
};
type SellerStore = {
  sellerId: string; storefrontName: string; planId: string; planStatus: 'active' | 'inactive' | 'pending';
  licenseStatus: Seller['licenseStatus']; followerCount: number; productCount: number; joined: boolean;
  deliveryEnabled: boolean; deliveryFee: number; deliveryRadius: string; deliveryEta: string;
};
type Membership = { sellerId: string; joinedAt: string; notificationsEnabled: boolean };

