const categories = ['All products', ...herbCategories];
const money = (value: number) => `$${value.toFixed(2)}`;
const iconForActivity = (type: string) => type === 'order' ? ClipboardList : type === 'inventory' ? Package : type === 'review' ? CircleAlert : Check;

function App() {
  const [products, setProducts] = useState(initialProducts);
  const [orders, setOrders] = useState(initialOrders);
  const [sellers, setSellers] = useState(initialSellers);
  const [favorites, setFavorites] = useState<string[]>(['p4']);
  const [bag, setBag] = useState<string[]>([]);
  const [ageConfirmed, setAgeConfirmed] = useState(false);
  const [location, setLocation] = useLocation();
  const [notice, setNotice] = useState('');
  const [search, setSearch] = useState('');
  const [posts, setPosts] = useState(initialPosts);
  const [comments, setComments] = useState(initialComments);
  const [locationSharing, setLocationSharing] = useState(false);
  const [locationPrecision, setLocationPrecision] = useState<'neighborhood' | 'approximate'>('neighborhood');
  const [conversations, setConversations] = useState(initialConversations);
  const [messages, setMessages] = useState(initialMessages);
  const [messagePrivacy, setMessagePrivacy] = useState<'everyone' | 'connections'>('everyone');
  const [storePlans] = useState(initialStorePlans);
  const [sellerStore, setSellerStore] = useState(initialSellerStores[0]);
  const [sellerStores, setSellerStores] = useState(initialSellerStores);
  const [memberships, setMemberships] = useState(initialMemberships);

  const flash = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 2600); };
  const toggleFavorite = (id: string) => {
    setFavorites((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
    flash(favorites.includes(id) ? 'Removed from saved items' : 'Saved to your favorites');
  };
  const addToBag = (id: string) => { setBag((current) => [...current, id]); flash('Added to your bag'); };
  const updateOrder = (id: string, status: Order['status']) => {
    setOrders((current) => current.map((order) => order.id === id ? { ...order, status } : order));
    flash(`Order ${id} marked ${status.toLowerCase()}`);
  };
  const updateSeller = (id: string, licenseStatus: Seller['licenseStatus']) => {
    setSellers((current) => current.map((seller) => seller.id === id ? { ...seller, licenseStatus } : seller));
    flash(licenseStatus === 'Verified' ? 'Seller verified and marketplace updated' : 'Seller moved to needs review');
  };
  const updateProduct = (id: string, changes: Partial<Product>) => {
    setProducts((current) => current.map((product) => product.id === id ? { ...product, ...changes } : product));
    flash('Inventory changes saved');
  };
  const addProduct = (changes: Partial<Product>) => {
    if (sellerStore.planStatus !== 'active') { flash('Rent a storefront plan before publishing products'); setLocation('/seller/plan'); return; }
    if (sellerStore.licenseStatus !== 'Verified') { flash('License review must be complete before publishing products'); return; }
    if (!changes.category || !herbCategories.includes(changes.category)) { flash('Only herb and herb-related categories can be listed'); return; }
    const currentPlan = storePlans.find((plan) => plan.id === sellerStore.planId);
    if (currentPlan?.listingLimit && products.filter((product) => product.seller === 'Juniper House').length >= currentPlan.listingLimit) { flash(`${currentPlan.name} plan listing limit reached`); return; }
    setProducts((current) => [...current, {
      id: `p${current.length + 1}`,
      name: changes.name || 'New catalog item',
       category: changes.category || 'Flower',
      seller: 'Juniper House',
      sellerVerified: true,
      price: changes.price || 30,
      unit: changes.unit || '3.5g',
      thc: changes.thc || 20,
      cbd: changes.cbd || 0.4,
      rating: 0,
      reviewCount: 0,
      image: 'sunset',
      stockStatus: changes.stockStatus || 'In stock',
    }]);
     setSellerStore((current) => ({ ...current, productCount: current.productCount + 1 }));
    flash('New product added to inventory');
  };
  const selectStorePlan = (planId: string) => {
    setSellerStore((current) => ({ ...current, planId, planStatus: 'pending' }));
    flash('Plan selected. Confirm the demo storefront rental to activate it.');
  };
  const activateStorefront = () => {
    setSellerStore((current) => ({ ...current, planStatus: 'active' }));
    setSellerStores((current) => current.map((store) => store.sellerId === 's1' ? { ...store, planId: sellerStore.planId, planStatus: 'active' } : store));
    flash('Demo storefront rental activated');
  };
  const cancelStorefront = () => {
    setSellerStore((current) => ({ ...current, planStatus: 'inactive' }));
    setSellerStores((current) => current.map((store) => store.sellerId === 's1' ? { ...store, planStatus: 'inactive' } : store));
    flash('Storefront rental cancelled; listings are paused');
  };
  const updateSellerDelivery = (changes: Partial<Pick<SellerStore, 'deliveryEnabled' | 'deliveryFee' | 'deliveryRadius' | 'deliveryEta'>>) => {
    setSellerStore((current) => ({ ...current, ...changes }));
    setSellerStores((current) => current.map((store) => store.sellerId === 's1' ? { ...store, ...changes } : store));
    flash(changes.deliveryEnabled === false ? 'Delivery turned off; pickup remains available' : 'Delivery settings saved');
  };
  const toggleMembership = (sellerId: string) => {
    const existing = memberships.find((membership) => membership.sellerId === sellerId);
    if (existing) {
      setMemberships((current) => current.filter((membership) => membership.sellerId !== sellerId));
      setSellerStores((current) => current.map((store) => store.sellerId === sellerId ? { ...store, followerCount: Math.max(0, store.followerCount - 1), joined: false } : store));
      flash('You left this seller store');
    } else {
      setMemberships((current) => [...current, { sellerId, joinedAt: 'Just now', notificationsEnabled: true }]);
      setSellerStores((current) => current.map((store) => store.sellerId === sellerId ? { ...store, followerCount: store.followerCount + 1, joined: true } : store));
      flash('You joined this seller store');
    }
  };
  const toggleStoreNotifications = (sellerId: string) => {
    setMemberships((current) => current.map((membership) => membership.sellerId === sellerId ? { ...membership, notificationsEnabled: !membership.notificationsEnabled } : membership));
  };
  const togglePost = (id: string, field: 'likes' | 'saved') => {
    setPosts((current) => current.map((post) => post.id === id ? { ...post, [field]: field === 'likes' ? (post.likes > 34 ? post.likes - 1 : post.likes + 1) : !post.saved } : post));
    flash(field === 'likes' ? 'Post reaction updated' : 'Saved posts updated');
  };
  const addComment = (postId: string, body: string) => {
    setComments((current) => [...current, { id: `comment-${current.length + 1}`, postId, author: 'Alex Morgan', body, createdAt: 'Just now' }]);
    setPosts((current) => current.map((post) => post.id === postId ? { ...post, comments: post.comments + 1 } : post));
    flash('Comment added to the conversation');
  };
  const createPost = (body: string, type: Post['type'], tags: string[]) => {
    setPosts((current) => [{ id: `post-${current.length + 1}`, author: 'Alex Morgan', handle: '@alexmorgan', avatar: 'AM', createdAt: 'Just now', body, type, locationLabel: 'San Francisco', tags, likes: 0, comments: 0, saved: false, verifiedAuthor: false }, ...current]);
    flash('Your post is live in the community');
  };
  const markConversationRead = (id: string) => {
    setConversations((current) => current.map((conversation) => conversation.id === id ? { ...conversation, unreadCount: 0 } : conversation));
  };
  const sendMessage = (conversationId: string, body: string) => {
    const now = new Date();
    const sentAt = now.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
    setMessages((current) => [...current, { id: `msg-${current.length + 1}`, conversationId, senderId: 'me', senderName: 'Alex Morgan', body, sentAt, isMine: true, status: 'sent' }]);
    setConversations((current) => current.map((conversation) => conversation.id === conversationId ? { ...conversation, lastMessage: body, lastMessageAt: 'Just now', unreadCount: 0 } : conversation));
    flash('Message sent');
  };
  const openSellerConversation = (placeName: string, initialMessage?: string) => {
    const existing = conversations.find((conversation) => conversation.kind === 'seller' && conversation.participantName === placeName);
    const id = `seller-${placeName.toLowerCase().replaceAll(/[^a-z0-9]+/g, '-')}`;
    if (existing) {
      markConversationRead(existing.id);
      if (initialMessage) sendMessage(existing.id, initialMessage);
      setLocation(`/messages/${existing.id}`);
      return;
    }
    setConversations((current) => [{ id, kind: 'seller', participantName: placeName, participantHandle: '@' + placeName.toLowerCase().replaceAll(/[^a-z0-9]+/g, ''), participantVerified: true, avatar: placeName.slice(0, 2).toUpperCase(), lastMessage: 'Start a licensed seller conversation', lastMessageAt: 'New', unreadCount: 0, contextLabel: 'Licensed place · demo availability', onlineStatus: 'online' }, ...current]);
    setMessages((current) => [...current, { id: `msg-${current.length + 1}`, conversationId: id, senderId: 'system', senderName: 'Greenline', body: `You can ask ${placeName} about licensed availability and pickup timing here.`, sentAt: 'Now', isMine: false, status: 'read' }]);
    if (initialMessage) setMessages((current) => [...current, { id: `msg-${current.length + 1}`, conversationId: id, senderId: 'me', senderName: 'Alex Morgan', body: initialMessage, sentAt: 'Now', isMine: true, status: 'sent' }]);
    setLocation(`/messages/${id}`);
  };
  const unreadCount = conversations.reduce((sum, conversation) => sum + conversation.unreadCount, 0);

  return (
    <QueryClientProvider client={queryClient}>
      <TooltipProvider>
        <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}>
          <RoutedErrorBoundary>
            <MarketplaceShell
              search={search}
              setSearch={setSearch}
              bagCount={bag.length}
              unreadCount={unreadCount}
              sellerStore={sellerStore}
              location={location}
              setLocation={setLocation}
            >
              <Switch>
                <Route path="/">
                  <SocialHome posts={posts} togglePost={togglePost} ageConfirmed={ageConfirmed} setAgeConfirmed={setAgeConfirmed} createPost={createPost} setLocation={setLocation} />
                </Route>
                <Route path="/discover">
                  <Discover posts={posts} places={nearbyPlaces.filter((place) => place.verified)} togglePost={togglePost} ageConfirmed={ageConfirmed} setAgeConfirmed={setAgeConfirmed} setLocation={setLocation} />
                </Route>
                <Route path="/map">
                  <MapWithMessaging places={nearbyPlaces.filter((place) => place.verified)} locationSharing={locationSharing} setLocationSharing={setLocationSharing} locationPrecision={locationPrecision} setLocationPrecision={setLocationPrecision} flash={flash} openSellerConversation={openSellerConversation} />
                </Route>
                <Route path="/post/:id">
                  <PostDetail posts={posts} comments={comments} togglePost={togglePost} addComment={addComment} />
                </Route>
                <Route path="/profile">
                  <ProfileWithMessaging posts={posts} togglePost={togglePost} locationSharing={locationSharing} setLocationSharing={setLocationSharing} locationPrecision={locationPrecision} setLocationPrecision={setLocationPrecision} flash={flash} />
                </Route>
                <Route path="/messages">
                  <MessagesInbox conversations={conversations} markConversationRead={markConversationRead} />
                </Route>
                <Route path="/messages/:conversationId">
                  <ConversationView conversations={conversations} messages={messages} markConversationRead={markConversationRead} sendMessage={sendMessage} />
                </Route>
                <Route path="/product/:id">
                  <ProductDetail products={products} sellerStores={sellerStores} favorites={favorites} toggleFavorite={toggleFavorite} addToBag={addToBag} bagCount={bag.length} openSellerConversation={openSellerConversation} />
                </Route>
                <Route path="/store/:sellerId">
                  <BuyerStorefront products={products} sellers={sellers} sellerStores={sellerStores} memberships={memberships} favorites={favorites} toggleFavorite={toggleFavorite} addToBag={addToBag} toggleMembership={toggleMembership} toggleStoreNotifications={toggleStoreNotifications} openSellerConversation={openSellerConversation} />
                </Route>
                <Route path="/seller/onboarding">
                  <SellerOnboarding sellerStore={sellerStore} selectPlan={selectStorePlan} activateStorefront={activateStorefront} storePlans={storePlans} />
                </Route>
                <Route path="/seller/store">
                  <SellerStoreManagement sellerStore={sellerStore} storePlans={storePlans} sellers={sellers} activateStorefront={activateStorefront} cancelStorefront={cancelStorefront} updateSellerDelivery={updateSellerDelivery} />
                </Route>
                <Route path="/seller/plan">
                  <SellerPlanPage sellerStore={sellerStore} storePlans={storePlans} selectStorePlan={selectStorePlan} activateStorefront={activateStorefront} cancelStorefront={cancelStorefront} />
                </Route>
                <Route path="/seller">
                  <SellerOverviewWithChat products={products} orders={orders} updateOrder={updateOrder} />
                </Route>
                <Route path="/seller/products">
                  <SellerProducts products={products} updateProduct={updateProduct} addProduct={addProduct} sellerStore={sellerStore} storePlans={storePlans} />
                </Route>
                <Route path="/seller/orders">
                  <SellerOrders orders={orders} updateOrder={updateOrder} />
                </Route>
                <Route path="/admin">
                  <AdminOverview sellers={sellers} orders={orders} products={products} />
                </Route>
                <Route path="/admin/sellers">
                  <AdminSellers sellers={sellers} updateSeller={updateSeller} />
                </Route>
                <Route path="/admin/orders">
                  <AdminOrders orders={orders} updateOrder={updateOrder} />
                </Route>
                <Route path="/settings">
                  <SocialSettings ageConfirmed={ageConfirmed} setAgeConfirmed={setAgeConfirmed} flash={flash} locationSharing={locationSharing} setLocationSharing={setLocationSharing} locationPrecision={locationPrecision} setLocationPrecision={setLocationPrecision} messagePrivacy={messagePrivacy} setMessagePrivacy={setMessagePrivacy} />
                </Route>
                <Route component={NotFound} />
              </Switch>
            </MarketplaceShell>
          </RoutedErrorBoundary>
        </WouterRouter>
        <Toaster />
        {notice && <div data-testid="status-toast" role="status" className="fixed bottom-5 left-1/2 z-50 -translate-x-1/2 rounded-full bg-[hsl(var(--foreground))] px-5 py-3 text-sm font-semibold text-[hsl(var(--background))] shadow-xl">{notice}</div>}
      </TooltipProvider>
    </QueryClientProvider>
  );
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>;
}

function MarketplaceShell({ children, search, setSearch, bagCount, unreadCount, sellerStore, location, setLocation }: {
  children: ReactNode; search: string; setSearch: (value: string) => void; bagCount: number; unreadCount: number; sellerStore: SellerStore; location: string; setLocation: (value: string) => void;
}) {
  const operational = location.startsWith('/seller') || location.startsWith('/admin');
  const [mobileOpen, setMobileOpen] = useState(false);
  if (operational) {
    return (
      <div className="min-h-[100dvh] bg-[hsl(var(--background))] text-[hsl(var(--foreground))]">
        <aside className={`fixed inset-y-0 left-0 z-40 w-[268px] border-r border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar))] px-5 py-6 text-[hsl(var(--sidebar-foreground))] transition-transform md:translate-x-0 ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}`}>
          <OpsRail current={location} setLocation={setLocation} close={() => setMobileOpen(false)} sellerStore={sellerStore} />
        </aside>
        {mobileOpen && <button aria-label="Close navigation" data-testid="button-close-navigation" onClick={() => setMobileOpen(false)} className="fixed inset-0 z-30 bg-[hsl(var(--foreground)/.38)] md:hidden" />}
        <main className="min-h-[100dvh] md:pl-[268px]">
          <div className="flex h-16 items-center justify-between border-b border-[hsl(var(--border))] bg-[hsl(var(--card)/.7)] px-5 backdrop-blur md:px-8">
            <button aria-label="Open navigation" data-testid="button-open-navigation" onClick={() => setMobileOpen(true)} className="rounded-lg p-2 hover:bg-[hsl(var(--muted))] md:hidden"><Menu size={20} /></button>
            <div className="hidden items-center gap-2 text-xs font-semibold text-[hsl(var(--muted-foreground))] md:flex"><span className="h-2 w-2 rounded-full bg-emerald-500" /> Marketplace operations / {location.startsWith('/admin') ? 'Admin console' : 'Seller workspace'}</div>
            <div className="ml-auto flex items-center gap-4"><button aria-label="Notifications" data-testid="button-notifications" className="relative rounded-lg p-2 hover:bg-[hsl(var(--muted))]"><Bell size={18} /><span className="absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent))]" /></button><div className="flex items-center gap-2 border-l border-[hsl(var(--border))] pl-4 text-sm font-semibold"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[hsl(var(--primary))] text-xs text-[hsl(var(--primary-foreground))]">AM</span><span className="hidden sm:inline">Alex Morgan</span><ChevronDown size={15} /></div></div>
          </div>
          {children}
        </main>
      </div>
    );
  }
  return (
    <div className="min-h-[100dvh] bg-[hsl(var(--background))] text-[hsl(var(--foreground))]">
      <header className="sticky top-0 z-30 border-b border-[hsl(var(--border))] bg-[hsl(var(--background)/.92)] backdrop-blur">
        <div className="mx-auto flex h-[72px] max-w-[1380px] items-center gap-5 px-5 md:px-8">
          <Link href="/" data-testid="link-brand" className="flex shrink-0 items-center gap-2.5 font-bold tracking-[-.04em]"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]"><Leaf size={19} strokeWidth={2.5} /></span><span className="text-lg">greenline<span className="text-[hsl(var(--accent-foreground))]">.</span></span></Link>
          <nav className="hidden items-center gap-4 text-sm font-semibold text-[hsl(var(--muted-foreground))] lg:flex"><Link href="/" data-testid="link-feed" className={location === '/' ? 'text-[hsl(var(--foreground))]' : 'hover:text-[hsl(var(--foreground))]'}>Feed</Link><Link href="/discover" data-testid="link-discover" className={location === '/discover' ? 'text-[hsl(var(--foreground))]' : 'hover:text-[hsl(var(--foreground))]'}>Discover</Link><Link href="/map" data-testid="link-map" className={location === '/map' ? 'text-[hsl(var(--foreground))]' : 'hover:text-[hsl(var(--foreground))]'}>Map</Link><span className="mx-1 h-4 w-px bg-[hsl(var(--border))]" /><Link href="/seller" data-testid="link-seller-workspace" className="text-xs hover:text-[hsl(var(--foreground))]">Seller</Link><Link href="/admin" data-testid="link-admin-console" className="text-xs hover:text-[hsl(var(--foreground))]">Admin</Link></nav>
          <label className="relative ml-auto hidden min-w-0 max-w-[330px] flex-1 md:block"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[hsl(var(--muted-foreground))]" /><input aria-label="Search community" data-testid="input-global-search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search the community" className="h-10 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] pl-9 pr-3 text-sm outline-none placeholder:text-[hsl(var(--muted-foreground))] focus:border-[hsl(var(--primary))] focus:ring-2 focus:ring-[hsl(var(--primary)/.15)]" /></label>
          <Link href="/messages" data-testid="link-messages" aria-label={`Messages${unreadCount ? `, ${unreadCount} unread` : ''}`} className="relative rounded-xl p-2.5 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))] hover:text-[hsl(var(--foreground))]"><MessageCircle size={20} />{unreadCount > 0 && <span data-testid="badge-unread-messages" className="absolute -right-0.5 -top-0.5 flex h-4 min-w-4 items-center justify-center rounded-full bg-[hsl(var(--accent))] px-1 text-[10px] font-bold">{unreadCount}</span>}</Link><Link href="/profile" data-testid="link-profile" aria-label="Profile" className="rounded-xl p-2.5 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))] hover:text-[hsl(var(--foreground))]"><UserCircle size={20} /></Link>
          <button data-testid="button-bag" aria-label={`Shopping bag with ${bagCount} items`} onClick={() => setLocation('/')} className="relative rounded-xl p-2.5 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))] hover:text-[hsl(var(--foreground))]"><ShoppingBag size={20} />{bagCount > 0 && <span className="absolute -right-0.5 -top-0.5 flex h-4 min-w-4 items-center justify-center rounded-full bg-[hsl(var(--accent))] px-1 text-[10px] font-bold">{bagCount}</span>}</button>
        </div>
        <div className="border-t border-[hsl(var(--border))] px-5 py-2.5 md:hidden"><label className="relative block"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[hsl(var(--muted-foreground))]" /><input aria-label="Search community mobile" data-testid="input-mobile-search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search community" className="h-9 w-full rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] pl-9 text-sm outline-none" /></label><div className="mt-2 flex items-center justify-between text-[11px] font-bold text-[hsl(var(--muted-foreground))]"><Link href="/" data-testid="link-mobile-feed" className="hover:text-[hsl(var(--foreground))]">Feed</Link><Link href="/discover" data-testid="link-mobile-discover">Discover</Link><Link href="/map" data-testid="link-mobile-map">Map</Link><Link href="/messages" data-testid="link-mobile-messages" className="relative">Messages{unreadCount > 0 && <span className="ml-1 rounded-full bg-[hsl(var(--accent))] px-1.5 py-0.5 text-[9px] text-[hsl(var(--accent-foreground))]">{unreadCount}</span>}</Link><Link href="/profile" data-testid="link-mobile-profile">Profile</Link></div></div>
      </header>
      {children}
    </div>
  );
}

function OpsRail({ current, setLocation, close, sellerStore }: { current: string; setLocation: (value: string) => void; close: () => void; sellerStore: SellerStore }) {
  const admin = current.startsWith('/admin');
  const links: { href: string; label: string; icon: LucideIcon }[] = admin ? [
    { href: '/admin', label: 'Overview', icon: BarChart3 }, { href: '/admin/sellers', label: 'Seller verification', icon: ShieldCheck }, { href: '/admin/orders', label: 'Order oversight', icon: ClipboardList },
  ] : [
    { href: '/seller', label: 'Workspace overview', icon: BarChart3 }, { href: '/seller/onboarding', label: 'Store setup', icon: Sparkles }, { href: '/seller/store', label: 'Storefront', icon: Store }, { href: '/seller/plan', label: 'Rental plan', icon: WalletCards }, { href: '/seller/products', label: 'Inventory', icon: Package }, { href: '/seller/orders', label: 'Order queue', icon: ClipboardList },
  ];
  return <div className="flex h-full flex-col"><div className="flex items-center justify-between"><Link href="/" data-testid="link-ops-brand" className="flex items-center gap-2.5 font-bold tracking-[-.04em]"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(var(--sidebar-primary))] text-[hsl(var(--sidebar-primary-foreground))]"><Leaf size={19} /></span><span className="text-lg">greenline<span className="text-[hsl(var(--sidebar-primary))]">.</span></span></Link><button onClick={close} aria-label="Close menu" className="rounded-lg p-1 md:hidden"><X size={18} /></button></div><div className="mt-12 px-3 text-[10px] font-bold uppercase tracking-[.17em] text-[hsl(var(--sidebar-foreground)/.55)]">{admin ? 'Admin console' : 'Seller workspace'}</div><nav className="mt-3 space-y-1">{links.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-${label.toLowerCase().replaceAll(' ', '-')}`} onClick={close} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold ${current === href ? 'bg-[hsl(var(--sidebar-accent))] text-[hsl(var(--sidebar-primary))]' : 'text-[hsl(var(--sidebar-foreground)/.7)] hover:bg-[hsl(var(--sidebar-accent))] hover:text-[hsl(var(--sidebar-foreground))]'}`}><Icon size={18} />{label}{href === '/admin/sellers' && <span className="ml-auto rounded-full bg-[hsl(var(--accent))] px-2 py-0.5 text-[10px] font-bold text-[hsl(var(--accent-foreground))]">2</span>}</Link>)}</nav>{!admin && <div className="mt-5 rounded-2xl border border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar-accent))] p-4"><div className="flex items-center justify-between text-xs font-bold"><span className="flex items-center gap-2"><WalletCards size={14} /> Rental plan</span><span className={sellerStore.planStatus === 'active' ? 'text-emerald-300' : 'text-amber-300'}>{sellerStore.planStatus === 'active' ? 'Active' : 'Needs setup'}</span></div><p className="mt-2 text-[11px] leading-relaxed text-[hsl(var(--sidebar-foreground)/.68)]">{sellerStore.planStatus === 'active' ? `${sellerStore.productCount} listings eligible on ${sellerStore.planId}.` : 'Rent a storefront before publishing listings.'}</p></div>}<div className="mt-auto space-y-3"><div className="rounded-2xl border border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar-accent))] p-4"><div className="mb-2 flex items-center gap-2 text-xs font-bold text-[hsl(var(--sidebar-primary))]"><ShieldCheck size={15} /> Compliance pulse</div><p className="text-xs leading-relaxed text-[hsl(var(--sidebar-foreground)/.68)]">All systems operational. Next license review in 6 days.</p></div><Link href="/settings" data-testid="link-ops-settings" className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-[hsl(var(--sidebar-foreground)/.7)] hover:bg-[hsl(var(--sidebar-accent))]"><Settings size={18} /> Workspace settings</Link></div></div>;
}

function Home({ products, favorites, toggleFavorite, addToBag, ageConfirmed, setAgeConfirmed, search, setSearch, setLocation }: { products: Product[]; favorites: string[]; toggleFavorite: (id: string) => void; addToBag: (id: string) => void; ageConfirmed: boolean; setAgeConfirmed: (value: boolean) => void; search: string; setSearch: (value: string) => void; setLocation: (value: string) => void }) {
  const [category, setCategory] = useState('All products');
  const [filterOpen, setFilterOpen] = useState(false);
  const filtered = useMemo(() => products.filter((product) => (category === 'All products' || product.category === category) && `${product.name} ${product.seller} ${product.category}`.toLowerCase().includes(search.toLowerCase())), [products, category, search]);
  return <div className="mx-auto max-w-[1380px] px-5 pb-16 md:px-8">
    {!ageConfirmed && <AgeGate onConfirm={() => setAgeConfirmed(true)} />}
    <section className="surface-grid relative mt-5 overflow-hidden rounded-[28px] bg-[hsl(var(--primary))] px-7 py-10 text-[hsl(var(--primary-foreground))] md:px-14 md:py-16"><div className="absolute -right-10 -top-20 h-72 w-72 rounded-full border-[40px] border-[hsl(var(--accent)/.28)]" /><div className="absolute bottom-[-110px] right-[17%] h-64 w-64 rounded-full bg-[hsl(var(--accent)/.12)] blur-2xl" /><div className="relative max-w-2xl"><div className="mb-5 flex items-center gap-2 text-xs font-bold uppercase tracking-[.18em] text-[hsl(var(--accent))]"><MapPin size={14} /> Serving San Francisco · 94107</div><h1 className="font-display text-5xl leading-[.96] tracking-[-.055em] md:text-7xl">Good products.<br /><em className="font-normal text-[hsl(var(--accent))]">Clear choices.</em></h1><p className="mt-6 max-w-lg text-base leading-relaxed text-[hsl(var(--primary-foreground)/.74)]">Discover cannabis from licensed neighborhood sellers, with the details you need to choose confidently.</p><div className="mt-8 flex flex-wrap gap-3"><button data-testid="button-find-nearby" onClick={() => document.getElementById('browse')?.scrollIntoView({ behavior: 'smooth' })} className="flex items-center gap-2 rounded-xl bg-[hsl(var(--accent))] px-4 py-3 text-sm font-bold text-[hsl(var(--accent-foreground))] hover:brightness-105">Find something nearby <ArrowRight size={16} /></button><button data-testid="button-how-it-works" onClick={() => setLocation('/settings')} className="rounded-xl border border-[hsl(var(--primary-foreground)/.25)] px-4 py-3 text-sm font-bold hover:bg-[hsl(var(--primary-foreground)/.1)]">How Greenline works</button></div></div><div className="relative mt-10 grid max-w-xl grid-cols-3 gap-5 border-t border-[hsl(var(--primary-foreground)/.18)] pt-5 text-xs md:absolute md:bottom-10 md:right-12 md:mt-0 md:w-[330px] md:border-t-0 md:pt-0"><div><div className="font-mono-ui text-xl text-[hsl(var(--accent))]">18</div><div className="mt-1 text-[hsl(var(--primary-foreground)/.6)]">licensed sellers</div></div><div><div className="font-mono-ui text-xl text-[hsl(var(--accent))]">1.4 mi</div><div className="mt-1 text-[hsl(var(--primary-foreground)/.6)]">closest pickup</div></div><div><div className="font-mono-ui text-xl text-[hsl(var(--accent))]">100%</div><div className="mt-1 text-[hsl(var(--primary-foreground)/.6)]">verified listings</div></div></div></section>
    <section id="browse" className="scroll-mt-24 pt-12"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="mb-2 text-xs font-bold uppercase tracking-[.17em] text-[hsl(var(--primary))]">Curated nearby</p><h2 className="font-display text-4xl tracking-[-.04em]">Find your next favorite.</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Every listing is tied to a licensed seller and a real pickup location.</p></div><button data-testid="button-filter-products" onClick={() => setFilterOpen(!filterOpen)} className={`flex items-center gap-2 self-start rounded-xl border px-3.5 py-2.5 text-sm font-bold md:self-auto ${filterOpen ? 'border-[hsl(var(--primary))] bg-[hsl(var(--primary)/.08)]' : 'border-[hsl(var(--border))] bg-[hsl(var(--card))]'}`}><SlidersHorizontal size={16} /> Filters <span className="font-mono-ui text-xs text-[hsl(var(--muted-foreground))]">0</span></button></div>{filterOpen && <div className="mt-5 flex flex-wrap items-center gap-3 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4 text-sm"><span className="font-semibold">Showing products available for pickup</span><span className="rounded-full bg-[hsl(var(--muted))] px-3 py-1 text-xs">Under 5 miles</span><span className="rounded-full bg-[hsl(var(--muted))] px-3 py-1 text-xs">Verified sellers only</span></div>}<div className="mt-7 flex gap-2 overflow-x-auto pb-2">{categories.map((item) => <button key={item} data-testid={`button-category-${item.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setCategory(item)} className={`shrink-0 rounded-full px-4 py-2 text-sm font-bold ${category === item ? 'bg-[hsl(var(--foreground))] text-[hsl(var(--background))]' : 'border border-[hsl(var(--border))] bg-[hsl(var(--card))] text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]'}`}>{item}</button>)}</div>{filtered.length ? <div className="mt-5 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-3">{filtered.map((product) => <ProductCard key={product.id} product={product} favorite={favorites.includes(product.id)} toggleFavorite={toggleFavorite} addToBag={addToBag} />)}</div> : <EmptyState search={search} onClear={() => { setSearch(''); setCategory('All products'); }} />}</section>
    <section className="mt-20 grid gap-5 border-t border-[hsl(var(--border))] pt-12 md:grid-cols-[1.1fr_.9fr]"><div><p className="mb-2 text-xs font-bold uppercase tracking-[.17em] text-[hsl(var(--primary))]">The Greenline standard</p><h2 className="font-display max-w-md text-4xl leading-tight tracking-[-.04em]">Trust should be part of the product.</h2><p className="mt-4 max-w-md text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">We make the signals that matter — licensing, freshness, distance, and availability — easy to see before you decide.</p></div><div className="grid gap-3 sm:grid-cols-3 md:pt-8"><TrustPill icon={BadgeCheck} title="Licensed sellers" text="Reviewed and verified" /><TrustPill icon={MapPin} title="Real distance" text="Pickup near you" /><TrustPill icon={ShieldCheck} title="Clear details" text="No guesswork" /></div></section>
  </div>;
}

function SocialHome({ posts, togglePost, ageConfirmed, setAgeConfirmed, createPost, setLocation }: { posts: Post[]; togglePost: (id: string, field: 'likes' | 'saved') => void; ageConfirmed: boolean; setAgeConfirmed: (value: boolean) => void; createPost: (body: string, type: Post['type'], tags: string[]) => void; setLocation: (value: string) => void }) {
  const [filter, setFilter] = useState<'All' | Post['type']>('All');
  const [query, setQuery] = useState('');
  const filtered = posts.filter((post) => (filter === 'All' || post.type === filter) && `${post.body} ${post.author} ${post.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));
  return <main className="mx-auto max-w-[1160px] px-5 pb-16 md:px-8">
    {!ageConfirmed && <AgeGate onConfirm={() => setAgeConfirmed(true)} />}
    <section className="relative overflow-hidden rounded-b-[30px] bg-[hsl(var(--primary))] px-6 py-10 text-[hsl(var(--primary-foreground))] md:px-12 md:py-14"><div className="absolute -right-16 -top-24 h-72 w-72 rounded-full border-[44px] border-[hsl(var(--accent)/.25)]" /><div className="relative max-w-2xl"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.17em] text-[hsl(var(--accent))]"><Compass size={15} /> Greenline community · San Francisco</div><h1 className="mt-4 max-w-2xl font-display text-5xl leading-[.94] tracking-[-.055em] md:text-7xl">A better way to<br /><em className="font-normal text-[hsl(var(--accent))]">talk cannabis.</em></h1><p className="mt-5 max-w-xl text-sm leading-relaxed text-[hsl(var(--primary-foreground)/.72)]">Local notes, honest questions, and activity from people who care about the details. Every place in Greenline is licensed. Every location signal stays in your control.</p><div className="mt-7 flex flex-wrap gap-3"><Link href="/discover" data-testid="link-hero-discover" className="flex items-center gap-2 rounded-xl bg-[hsl(var(--accent))] px-4 py-3 text-sm font-bold text-[hsl(var(--accent-foreground))]">See what is nearby <ArrowRight size={16} /></Link><button data-testid="button-hero-compose" onClick={() => document.getElementById('compose')?.focus()} className="rounded-xl border border-[hsl(var(--primary-foreground)/.24)] px-4 py-3 text-sm font-bold hover:bg-[hsl(var(--primary-foreground)/.1)]">Share a note</button></div></div><div className="relative mt-10 grid grid-cols-3 gap-5 border-t border-[hsl(var(--primary-foreground)/.17)] pt-5 text-xs md:absolute md:bottom-10 md:right-12 md:w-[300px] md:border-0 md:pt-0"><div><div className="font-mono-ui text-xl text-[hsl(var(--accent))]">24</div><div className="mt-1 text-[hsl(var(--primary-foreground)/.6)]">local voices</div></div><div><div className="font-mono-ui text-xl text-[hsl(var(--accent))]">4</div><div className="mt-1 text-[hsl(var(--primary-foreground)/.6)]">licensed places</div></div><div><div className="font-mono-ui text-xl text-[hsl(var(--accent))]">1.4 mi</div><div className="mt-1 text-[hsl(var(--primary-foreground)/.6)]">closest pickup</div></div></div></section>
    <div className="grid gap-8 pt-10 lg:grid-cols-[minmax(0,1fr)_290px]"><div className="min-w-0"><ComposeCard onSubmit={createPost} /><div className="mt-8 flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-[.17em] text-[hsl(var(--primary))]">The neighborhood thread</p><h2 className="mt-1 font-display text-3xl tracking-[-.04em]">What is happening nearby</h2></div><label className="relative"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[hsl(var(--muted-foreground))]" /><input data-testid="input-feed-search" aria-label="Search community posts" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search posts" className="h-9 w-full rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] pl-9 pr-3 text-xs outline-none sm:w-44" /></label></div><div className="mt-4 flex gap-2 overflow-x-auto pb-2">{(['All', 'Discussion', 'Strain note', 'Local activity'] as const).map((item) => <button key={item} data-testid={`button-feed-filter-${item.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setFilter(item)} className={`shrink-0 rounded-full px-3.5 py-2 text-xs font-bold ${filter === item ? 'bg-[hsl(var(--foreground))] text-[hsl(var(--background))]' : 'border border-[hsl(var(--border))] bg-[hsl(var(--card))] text-[hsl(var(--muted-foreground))]'}`}>{item}</button>)}</div><div className="mt-3 space-y-3">{filtered.map((post) => <PostCard key={post.id} post={post} togglePost={togglePost} />)}</div>{!filtered.length && <div className="rounded-2xl border border-dashed p-12 text-center"><Search className="mx-auto text-[hsl(var(--muted-foreground))]" /><p className="mt-3 font-display text-2xl">No posts found</p><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Try a different tag or start a new conversation.</p></div>}</div><aside className="space-y-4"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.15em] text-[hsl(var(--primary))]">Around you</p><h3 className="mt-1 font-display text-2xl">In the neighborhood</h3></div><MapPin size={18} className="text-[hsl(var(--primary))]" /></div><p className="mt-3 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">You are browsing from <span className="font-bold text-[hsl(var(--foreground))]">Mission District</span>. Precise location is never shown to other people.</p><Link href="/map" data-testid="link-sidebar-map" className="mt-5 flex items-center justify-center gap-2 rounded-xl bg-[hsl(var(--secondary))] py-2.5 text-xs font-bold">Open local map <Navigation size={14} /></Link></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center gap-2 text-sm font-bold"><ShieldCheck size={16} className="text-[hsl(var(--primary))]" /> Greenline signals</div><p className="mt-3 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">Verified badges belong to licensed sellers and community contributors who completed age and identity checks. Demo activity is clearly marked.</p><button data-testid="button-learn-signals" onClick={() => setLocation('/settings')} className="mt-4 text-xs font-bold text-[hsl(var(--primary))]">Review privacy controls <ArrowRight size={13} className="ml-1 inline" /></button></div></aside></div>
  </main>;
}

function ComposeCard({ onSubmit }: { onSubmit: (body: string, type: Post['type'], tags: string[]) => void }) {
  const [body, setBody] = useState('');
  const [type, setType] = useState<Post['type']>('Discussion');
  return <div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4 shadow-[0_8px_24px_hsl(var(--foreground)/.03)]"><div className="flex gap-3"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-[hsl(var(--primary))] text-xs font-bold text-[hsl(var(--primary-foreground))]">AM</div><textarea id="compose" data-testid="input-compose-post" aria-label="Share with the community" value={body} onChange={(e) => setBody(e.target.value)} placeholder="Share a local note, ask a question, or start a strain conversation..." className="min-h-[76px] flex-1 resize-none bg-transparent pt-1 text-sm outline-none placeholder:text-[hsl(var(--muted-foreground))]" /></div><div className="mt-3 flex flex-wrap items-center justify-between gap-3 border-t border-[hsl(var(--border))] pt-3"><div className="flex items-center gap-2"><Tag size={14} className="text-[hsl(var(--muted-foreground))]" /><select data-testid="select-compose-type" aria-label="Post type" value={type} onChange={(e) => setType(e.target.value as Post['type'])} className="rounded-lg bg-[hsl(var(--muted))] px-2 py-1.5 text-xs font-bold"><option>Discussion</option><option>Strain note</option><option>Local activity</option></select></div><button data-testid="button-publish-post" disabled={!body.trim()} onClick={() => { onSubmit(body.trim(), type, [type.toLowerCase().replace(' ', '-')]); setBody(''); }} className="flex items-center gap-2 rounded-lg bg-[hsl(var(--primary))] px-3.5 py-2 text-xs font-bold text-[hsl(var(--primary-foreground))] opacity-50 enabled:opacity-100"><Send size={14} /> Post to Greenline</button></div></div>;
}

function PostCard({ post, togglePost }: { post: Post; togglePost: (id: string, field: 'likes' | 'saved') => void }) {
  return <article data-testid={`card-post-${post.id}`} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 hover:border-[hsl(var(--primary)/.4)]"><div className="flex items-start gap-3"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-[hsl(var(--secondary))] text-xs font-bold text-[hsl(var(--primary))]">{post.avatar}</div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><span className="text-sm font-bold">{post.author}</span>{post.verifiedAuthor && <BadgeCheck size={14} className="text-[hsl(var(--primary))]" />}<span className="text-xs text-[hsl(var(--muted-foreground))]">{post.handle}</span><span className="ml-auto text-xs text-[hsl(var(--muted-foreground))]">{post.createdAt}</span></div><div className="mt-0.5 flex items-center gap-1 text-[11px] text-[hsl(var(--muted-foreground))]"><MapPin size={11} /> {post.locationLabel} <span>·</span> <span className="font-semibold text-[hsl(var(--primary))]">{post.type}</span></div><Link href={`/post/${post.id}`} data-testid={`link-post-${post.id}`} className="mt-4 block text-[15px] leading-relaxed hover:text-[hsl(var(--primary))]">{post.body}</Link><div className="mt-3 flex flex-wrap gap-1.5">{post.tags.map((tag) => <span key={tag} className="rounded-full bg-[hsl(var(--muted))] px-2.5 py-1 text-[10px] font-semibold text-[hsl(var(--muted-foreground))]">#{tag}</span>)}</div><div className="mt-4 flex items-center gap-1 border-t border-[hsl(var(--border))] pt-3"><button data-testid={`button-like-post-${post.id}`} aria-label={`Like post by ${post.author}`} onClick={() => togglePost(post.id, 'likes')} className="flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs font-semibold text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]"><ThumbsUp size={14} /> {post.likes}</button><Link href={`/post/${post.id}`} data-testid={`link-comments-${post.id}`} className="flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs font-semibold text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]"><MessageCircle size={14} /> {post.comments}</Link><button data-testid={`button-save-post-${post.id}`} aria-label={post.saved ? 'Unsave post' : 'Save post'} onClick={() => togglePost(post.id, 'saved')} className={`ml-auto rounded-lg p-1.5 ${post.saved ? 'text-[hsl(var(--primary))]' : 'text-[hsl(var(--muted-foreground))]'} hover:bg-[hsl(var(--muted))]`}><Bookmark size={15} fill={post.saved ? 'currentColor' : 'none'} /></button><button data-testid={`button-more-post-${post.id}`} aria-label="More post actions" className="rounded-lg p-1.5 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]"><MoreHorizontal size={16} /></button></div></div></div></article>;
}

function Discover({ posts, places, togglePost, ageConfirmed, setAgeConfirmed, setLocation }: { posts: Post[]; places: NearbyPlace[]; togglePost: (id: string, field: 'likes' | 'saved') => void; ageConfirmed: boolean; setAgeConfirmed: (value: boolean) => void; setLocation: (value: string) => void }) {
  const [tab, setTab] = useState<'Places' | 'Activity'>('Places');
  return <main className="mx-auto max-w-[1160px] px-5 pb-16 md:px-8">{!ageConfirmed && <AgeGate onConfirm={() => setAgeConfirmed(true)} />}<div className="border-b border-[hsl(var(--border))] py-10"><p className="text-xs font-bold uppercase tracking-[.17em] text-[hsl(var(--primary))]">Discover locally</p><div className="mt-2 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><h1 className="font-display text-5xl tracking-[-.05em]">Your local greenline.</h1><p className="mt-3 max-w-xl text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">Find licensed places, pickup points, and the conversations happening within a few miles of your neighborhood.</p></div><Link href="/map" data-testid="link-discover-map" className="flex items-center gap-2 self-start rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-sm font-bold text-[hsl(var(--primary-foreground))]"><MapPin size={16} /> Open map</Link></div></div><div className="mt-8 flex gap-2"><button data-testid="button-discover-places" onClick={() => setTab('Places')} className={`rounded-full px-4 py-2 text-sm font-bold ${tab === 'Places' ? 'bg-[hsl(var(--foreground))] text-[hsl(var(--background))]' : 'border border-[hsl(var(--border))]'}`}>Nearby places</button><button data-testid="button-discover-activity" onClick={() => setTab('Activity')} className={`rounded-full px-4 py-2 text-sm font-bold ${tab === 'Activity' ? 'bg-[hsl(var(--foreground))] text-[hsl(var(--background))]' : 'border border-[hsl(var(--border))]'}`}>Community activity</button></div>{tab === 'Places' ? <div className="mt-5 grid gap-4 md:grid-cols-2">{places.map((place) => <PlaceCard key={place.id} place={place} onSelect={() => setLocation('/map')} />)}</div> : <div className="mt-5 max-w-2xl space-y-3">{posts.map((post) => <PostCard key={post.id} post={post} togglePost={togglePost} />)}</div>}<div className="mt-8 rounded-2xl border border-[hsl(var(--accent)/.45)] bg-[hsl(var(--accent)/.12)] p-5 text-sm"><div className="flex items-center gap-2 font-bold"><ShieldCheck size={16} /> Demo availability, real-world responsibility</div><p className="mt-2 max-w-2xl text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">Place hours and product counts are demo data for this prototype. Only licensed and verified places appear. Greenline does not facilitate anonymous or unlicensed transactions.</p></div></main>;
}

function PlaceCard({ place, onSelect }: { place: NearbyPlace; onSelect: () => void }) {
  return <button data-testid={`button-place-${place.id}`} onClick={onSelect} className="group text-left rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 hover:-translate-y-0.5 hover:border-[hsl(var(--primary)/.5)]"><div className="flex items-start justify-between"><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Store size={20} /></div><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${place.openNow ? 'bg-emerald-100 text-emerald-800' : 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]'}`}>{place.openNow ? 'Open now' : 'Closed'}</span></div><h3 className="mt-5 text-lg font-bold">{place.name}</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{place.kind} · {place.distance}</p><p className="mt-3 flex items-center gap-1.5 text-xs text-[hsl(var(--muted-foreground))]"><MapPin size={13} /> {place.address}</p><div className="mt-5 flex items-center justify-between border-t border-[hsl(var(--border))] pt-3 text-xs"><span className="flex items-center gap-1 font-semibold"><BadgeCheck size={14} className="text-[hsl(var(--primary))]" /> Licensed place</span><span>{place.products} demo listings <ArrowRight className="ml-1 inline group-hover:translate-x-0.5" size={13} /></span></div></button>;
}

function MapWithMessaging({ places, locationSharing, setLocationSharing, locationPrecision, setLocationPrecision, flash, openSellerConversation }: { places: NearbyPlace[]; locationSharing: boolean; setLocationSharing: (value: boolean) => void; locationPrecision: 'neighborhood' | 'approximate'; setLocationPrecision: (value: 'neighborhood' | 'approximate') => void; flash: (message: string) => void; openSellerConversation: (placeName: string) => void }) {
  return <div className="relative"><MapPage places={places} locationSharing={locationSharing} setLocationSharing={setLocationSharing} locationPrecision={locationPrecision} setLocationPrecision={setLocationPrecision} flash={flash} openSellerConversation={openSellerConversation} /><div className="fixed bottom-6 right-5 z-20 flex gap-2 md:right-8"><Link href="/store/s1" data-testid="link-map-storefront" className="flex items-center gap-2 rounded-full border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 py-3 text-xs font-bold shadow-xl"><Store size={15} /> Visit Juniper</Link><Link href="/messages/seller-juniper" data-testid="link-map-message-seller" className="flex items-center gap-2 rounded-full bg-[hsl(var(--primary))] px-4 py-3 text-xs font-bold text-[hsl(var(--primary-foreground))] shadow-xl"><MessageCircle size={15} /> Message place</Link></div></div>;
}

function MapPage({ places, locationSharing, setLocationSharing, locationPrecision, setLocationPrecision, flash, openSellerConversation }: { places: NearbyPlace[]; locationSharing: boolean; setLocationSharing: (value: boolean) => void; locationPrecision: 'neighborhood' | 'approximate'; setLocationPrecision: (value: 'neighborhood' | 'approximate') => void; flash: (message: string) => void; openSellerConversation: (placeName: string) => void }) {
  const [geoState, setGeoState] = useState<'idle' | 'requesting' | 'granted' | 'denied'>('idle');
  const [selected, setSelected] = useState(places[0]);
  const [neighborhood, setNeighborhood] = useState('Mission District');
  const requestLocation = () => {
    setGeoState('requesting');
    if (!navigator.geolocation) { setGeoState('denied'); return; }
    navigator.geolocation.getCurrentPosition(() => { setGeoState('granted'); setLocationSharing(true); flash('Approximate location is active'); }, () => setGeoState('denied'), { enableHighAccuracy: false, timeout: 5000 });
  };
  return <main className="mx-auto max-w-[1280px] px-5 pb-16 md:px-8"><div className="flex flex-col justify-between gap-5 py-8 md:flex-row md:items-end"><div><p className="text-xs font-bold uppercase tracking-[.17em] text-[hsl(var(--primary))]">Nearby map</p><h1 className="mt-2 font-display text-5xl tracking-[-.05em]">Your corner of Greenline.</h1><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Licensed dispensaries and pickup points only. Location stays private by default.</p></div><div className="flex items-center gap-2"><Link href="/discover" data-testid="link-map-discover" className="rounded-xl border border-[hsl(var(--border))] px-3 py-2 text-xs font-bold">List view</Link><button data-testid="button-map-locate" onClick={requestLocation} className="flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-3 py-2 text-xs font-bold text-[hsl(var(--primary-foreground))]"><LocateFixed size={15} /> {geoState === 'requesting' ? 'Requesting…' : 'Use my location'}</button></div></div><div className="grid gap-5 lg:grid-cols-[1.25fr_.75fr]"><div className="relative min-h-[560px] overflow-hidden rounded-[26px] border border-[hsl(var(--border))] bg-[#d9dfd0] surface-grid"><div className="absolute inset-x-[8%] top-[32%] h-1 rotate-[18deg] bg-[hsl(var(--card)/.8)] shadow-[0_0_0_3px_hsl(var(--primary)/.07)]" /><div className="absolute inset-y-[10%] left-[47%] w-1 -rotate-[30deg] bg-[hsl(var(--card)/.8)] shadow-[0_0_0_3px_hsl(var(--primary)/.07)]" /><div className="absolute left-[18%] top-[14%] h-32 w-48 rounded-[50%] border-2 border-[hsl(var(--primary)/.12)]" /><div className="absolute bottom-[11%] right-[8%] h-40 w-52 rounded-[50%] border-2 border-[hsl(var(--primary)/.12)]" />{places.map((place, index) => <button key={place.id} data-testid={`button-map-marker-${place.id}`} onClick={() => setSelected(place)} className={`absolute z-10 flex -translate-x-1/2 -translate-y-1/2 items-center gap-1.5 rounded-full border-2 border-[hsl(var(--card))] px-2.5 py-1.5 text-[10px] font-bold shadow-lg ${selected.id === place.id ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] scale-110' : 'bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]'}`} style={{ left: `${20 + index * 21}%`, top: `${28 + (index % 3) * 22}%` }}><MapPin size={13} /> {place.name}</button>)}{locationSharing && <div data-testid="map-user-location" className="absolute left-[53%] top-[53%] -translate-x-1/2 -translate-y-1/2"><span className="absolute -inset-4 animate-pulse rounded-full bg-[hsl(var(--primary)/.18)]" /><span className="relative block h-4 w-4 rounded-full border-2 border-[hsl(var(--card))] bg-[hsl(var(--primary))]" /></div>}<div className="absolute bottom-4 left-4 rounded-xl bg-[hsl(var(--card)/.9)] px-3 py-2 text-[10px] font-semibold shadow backdrop-blur"><span className="mr-1.5 inline-block h-2 w-2 rounded-full bg-[hsl(var(--accent))]" /> Demo place data · private map</div></div><aside className="space-y-4"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.15em] text-[hsl(var(--primary))]">Location permission</p><h2 className="mt-1 font-display text-2xl">{geoState === 'granted' ? 'You are on the map.' : 'Stay private by default.'}</h2></div><Crosshair size={19} className="text-[hsl(var(--primary))]" /></div><p className="mt-3 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">{geoState === 'granted' ? 'Greenline uses an approximate browser signal to sort nearby places. Your precise coordinates are not shown to people or shared with sellers.' : 'Greenline can use your browser location to sort nearby places. You can also choose a neighborhood instead — nothing is shared until you ask.'}</p>{geoState === 'denied' && <p className="mt-3 rounded-lg bg-amber-100 p-2.5 text-xs font-semibold text-amber-800">Location permission was not granted. Choose a neighborhood below.</p>}<button data-testid="button-toggle-location-sharing" onClick={() => { setLocationSharing(!locationSharing); flash(locationSharing ? 'Location sharing turned off' : 'Approximate location sharing turned on'); }} className={`mt-4 w-full rounded-xl py-2.5 text-xs font-bold ${locationSharing ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'bg-[hsl(var(--secondary))]'}`}>{locationSharing ? 'Sharing approximate location' : 'Keep location private'}</button></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><label className="text-xs font-bold uppercase tracking-[.14em]">Fallback neighborhood<select data-testid="select-map-neighborhood" aria-label="Choose neighborhood" value={neighborhood} onChange={(e) => { setNeighborhood(e.target.value); setLocationPrecision('neighborhood'); }} className="mt-2 h-11 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3 text-sm"><option>Mission District</option><option>North Park</option><option>Bernal Heights</option><option>Ocean Beach</option></select></label><div className="mt-5 flex items-center justify-between border-t border-[hsl(var(--border))] pt-4"><div><p className="text-sm font-semibold">Precision</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{locationPrecision === 'neighborhood' ? 'Neighborhood only' : 'Approximate pin'}</p></div><button data-testid="button-toggle-precision" onClick={() => setLocationPrecision(locationPrecision === 'neighborhood' ? 'approximate' : 'neighborhood')} className="rounded-lg border border-[hsl(var(--border))] px-3 py-2 text-xs font-bold">{locationPrecision === 'neighborhood' ? 'Use approximate' : 'Use neighborhood'}</button></div></div><PlaceCard place={selected} onSelect={() => flash(`${selected.name} selected`)} /></aside></div></main>;
}

function PostDetail({ posts, comments, togglePost, addComment }: { posts: Post[]; comments: Comment[]; togglePost: (id: string, field: 'likes' | 'saved') => void; addComment: (postId: string, body: string) => void }) {
  const { id } = useParams<{ id: string }>();
  const post = posts.find((item) => item.id === id) ?? posts[0];
  const [body, setBody] = useState('');
  const [reported, setReported] = useState(false);
  const thread = comments.filter((comment) => comment.postId === post.id);
  return <main className="mx-auto max-w-[820px] px-5 py-8 md:px-8 md:py-12"><Link href="/" data-testid="link-back-feed" className="text-sm font-semibold text-[hsl(var(--muted-foreground))]">← Back to feed</Link><div className="mt-7"><PostCard post={post} togglePost={togglePost} /></div><div className="mt-5 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center justify-between"><h2 className="font-display text-2xl">Conversation <span className="font-mono-ui text-sm text-[hsl(var(--muted-foreground))]">{thread.length}</span></h2><button data-testid="button-report-post" onClick={() => setReported(true)} className="flex items-center gap-1.5 text-xs font-semibold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--destructive))]">{reported ? <Check size={14} /> : <CircleAlert size={14} />} {reported ? 'Report received' : 'Report post'}</button></div>{reported && <p className="mt-3 rounded-lg bg-[hsl(var(--muted))] p-3 text-xs">Thanks. Our community team will review this report. No action is taken automatically.</p>}<div className="mt-5 space-y-4">{thread.map((comment) => <div key={comment.id} data-testid={`comment-${comment.id}`} className="flex gap-3"><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[hsl(var(--secondary))] text-[10px] font-bold text-[hsl(var(--primary))]">{comment.author.split(' ').map((n) => n[0]).join('')}</div><div className="rounded-xl bg-[hsl(var(--muted)/.7)] px-3 py-2.5"><div className="flex items-center gap-2 text-xs font-bold">{comment.author}<span className="font-normal text-[hsl(var(--muted-foreground))]">{comment.createdAt}</span></div><p className="mt-1 text-sm leading-relaxed">{comment.body}</p></div></div>)}</div><div className="mt-6 flex gap-3 border-t border-[hsl(var(--border))] pt-5"><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[hsl(var(--primary))] text-[10px] font-bold text-[hsl(var(--primary-foreground))]">AM</div><input data-testid="input-comment" aria-label="Write a comment" value={body} onChange={(e) => setBody(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && body.trim()) { addComment(post.id, body.trim()); setBody(''); } }} placeholder="Add something thoughtful..." className="h-10 flex-1 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3 text-sm outline-none" /><button data-testid="button-submit-comment" disabled={!body.trim()} onClick={() => { addComment(post.id, body.trim()); setBody(''); }} className="rounded-xl bg-[hsl(var(--primary))] px-3 text-[hsl(var(--primary-foreground))] opacity-50 enabled:opacity-100"><Send size={16} /></button></div></div></main>;
}

function ProfileWithMessaging({ posts, togglePost, locationSharing, setLocationSharing, locationPrecision, setLocationPrecision, flash }: { posts: Post[]; togglePost: (id: string, field: 'likes' | 'saved') => void; locationSharing: boolean; setLocationSharing: (value: boolean) => void; locationPrecision: 'neighborhood' | 'approximate'; setLocationPrecision: (value: 'neighborhood' | 'approximate') => void; flash: (message: string) => void }) {
  return <div className="relative"><ProfilePage posts={posts} togglePost={togglePost} locationSharing={locationSharing} setLocationSharing={setLocationSharing} locationPrecision={locationPrecision} setLocationPrecision={setLocationPrecision} flash={flash} /><Link href="/messages/friend-maya" data-testid="link-message-profile-friend" className="fixed bottom-6 right-5 z-20 flex items-center gap-2 rounded-full bg-[hsl(var(--primary))] px-4 py-3 text-xs font-bold text-[hsl(var(--primary-foreground))] shadow-xl md:right-8"><MessageCircle size={15} /> Message Maya</Link></div>;
}

function ProfilePage({ posts, togglePost, locationSharing, setLocationSharing, locationPrecision, setLocationPrecision, flash }: { posts: Post[]; togglePost: (id: string, field: 'likes' | 'saved') => void; locationSharing: boolean; setLocationSharing: (value: boolean) => void; locationPrecision: 'neighborhood' | 'approximate'; setLocationPrecision: (value: 'neighborhood' | 'approximate') => void; flash: (message: string) => void }) {
  const [tab, setTab] = useState<'posts' | 'saved'>('posts');
  const shown = tab === 'saved' ? posts.filter((post) => post.saved) : posts.filter((post) => post.handle === '@alexmorgan');
  return <main className="mx-auto max-w-[1000px] px-5 pb-16 md:px-8"><div className="mt-8 overflow-hidden rounded-[26px] border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="h-28 bg-[hsl(var(--primary))] surface-grid" /><div className="px-6 pb-6"><div className="-mt-7 flex items-end justify-between"><div className="flex h-16 w-16 items-center justify-center rounded-full border-4 border-[hsl(var(--card))] bg-[hsl(var(--accent))] text-lg font-bold">AM</div><button data-testid="button-edit-profile-social" onClick={() => flash('Profile editing is ready for your details')} className="rounded-xl border border-[hsl(var(--border))] px-3 py-2 text-xs font-bold">Edit profile</button></div><h1 className="mt-4 font-display text-3xl">Alex Morgan</h1><p className="text-sm text-[hsl(var(--muted-foreground))]">@alexmorgan · San Francisco</p><p className="mt-4 max-w-xl text-sm leading-relaxed">Curious about thoughtful products, neighborhood pickup, and what works for real evenings.</p></div></div><div className="mt-7 grid gap-5 lg:grid-cols-[1fr_320px]"><div><div className="flex gap-2 border-b border-[hsl(var(--border))] pb-3"><button data-testid="button-profile-posts" onClick={() => setTab('posts')} className={`px-3 py-2 text-sm font-bold ${tab === 'posts' ? 'border-b-2 border-[hsl(var(--primary))] text-[hsl(var(--primary))]' : 'text-[hsl(var(--muted-foreground))]'}`}>My posts</button><button data-testid="button-profile-saved" onClick={() => setTab('saved')} className={`px-3 py-2 text-sm font-bold ${tab === 'saved' ? 'border-b-2 border-[hsl(var(--primary))] text-[hsl(var(--primary))]' : 'text-[hsl(var(--muted-foreground))]'}`}>Saved posts</button></div><div className="mt-4 space-y-3">{shown.length ? shown.map((post) => <PostCard key={post.id} post={post} togglePost={togglePost} />) : <div className="rounded-2xl border border-dashed p-12 text-center text-sm text-[hsl(var(--muted-foreground))]">Your saved conversations will appear here.</div>}</div></div><div className="space-y-4"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><h2 className="flex items-center gap-2 font-semibold"><Globe2 size={17} className="text-[hsl(var(--primary))]" /> Privacy and location</h2><p className="mt-2 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">Your exact location is never published to the community or exposed to sellers.</p><div className="mt-5 flex items-center justify-between border-t border-[hsl(var(--border))] pt-4"><div><p className="text-sm font-semibold">Location sharing</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{locationSharing ? 'Approximate only' : 'Off'}</p></div><button data-testid="button-profile-location" aria-pressed={locationSharing} onClick={() => { setLocationSharing(!locationSharing); flash(locationSharing ? 'Location sharing turned off' : 'Approximate location sharing turned on'); }} className={`h-6 w-11 rounded-full ${locationSharing ? 'bg-[hsl(var(--primary))]' : 'bg-[hsl(var(--muted))]'}`}><span className={`mx-1 block h-4 w-4 rounded-full bg-[hsl(var(--card))] transition-transform ${locationSharing ? 'translate-x-5' : ''}`} /></button></div><div className="mt-4 flex items-center justify-between"><div><p className="text-sm font-semibold">Location precision</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{locationPrecision === 'neighborhood' ? 'Neighborhood' : 'Approximate pin'}</p></div><button data-testid="button-profile-precision" onClick={() => setLocationPrecision(locationPrecision === 'neighborhood' ? 'approximate' : 'neighborhood')} className="rounded-lg border border-[hsl(var(--border))] px-2.5 py-1.5 text-[11px] font-bold">Change</button></div></div><Link href="/settings" data-testid="link-profile-settings" className="flex items-center justify-between rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 text-sm font-bold">Account settings <ArrowRight size={16} /></Link></div></div></main>;
}

function MessagesInbox({ conversations, markConversationRead }: { conversations: Conversation[]; markConversationRead: (id: string) => void }) {
  const [query, setQuery] = useState('');
  const filtered = conversations.filter((conversation) => `${conversation.participantName} ${conversation.participantHandle} ${conversation.lastMessage} ${conversation.contextLabel}`.toLowerCase().includes(query.toLowerCase()));
  const unread = conversations.reduce((sum, conversation) => sum + conversation.unreadCount, 0);
  return <main className="mx-auto max-w-[980px] px-5 pb-16 md:px-8"><div className="flex flex-col justify-between gap-5 border-b border-[hsl(var(--border))] py-8 md:flex-row md:items-end"><div><p className="text-xs font-bold uppercase tracking-[.17em] text-[hsl(var(--primary))]">Community messages</p><h1 className="mt-2 font-display text-5xl tracking-[-.05em]">Stay in the loop.</h1><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">{unread ? `${unread} unread ${unread === 1 ? 'message' : 'messages'}` : 'You are all caught up'} · seller and friend conversations in one calm place.</p></div><div className="relative w-full md:w-64"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[hsl(var(--muted-foreground))]" /><input data-testid="input-message-search" aria-label="Search conversations" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search conversations" className="h-10 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] pl-9 pr-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /></div></div><div className="mt-7 grid gap-5 lg:grid-cols-[1fr_280px]"><div className="space-y-3">{filtered.length ? filtered.map((conversation) => <Link key={conversation.id} href={`/messages/${conversation.id}`} data-testid={`link-conversation-${conversation.id}`} onClick={() => markConversationRead(conversation.id)} className="flex items-center gap-4 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4 text-left hover:-translate-y-0.5 hover:border-[hsl(var(--primary)/.4)]"><div className={`relative flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl text-sm font-bold ${conversation.kind === 'seller' ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]'}`}>{conversation.avatar}<span className={`absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full border-2 border-[hsl(var(--card))] ${conversation.onlineStatus === 'online' ? 'bg-emerald-500' : conversation.onlineStatus === 'away' ? 'bg-amber-400' : 'bg-[hsl(var(--muted-foreground))]'}`} /></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><span className="font-bold">{conversation.participantName}</span>{conversation.participantVerified && <BadgeCheck size={14} className="text-[hsl(var(--primary))]" />}<span className="ml-auto shrink-0 text-xs text-[hsl(var(--muted-foreground))]">{conversation.lastMessageAt}</span></div><div className="mt-0.5 flex items-center gap-2 text-[11px] text-[hsl(var(--muted-foreground))]"><span className={`font-bold ${conversation.kind === 'seller' ? 'text-[hsl(var(--primary))]' : ''}`}>{conversation.kind === 'seller' ? 'Licensed seller' : 'Community friend'}</span><span>·</span><span className="truncate">{conversation.contextLabel}</span></div><p className={`mt-2 truncate text-sm ${conversation.unreadCount ? 'font-bold' : 'text-[hsl(var(--muted-foreground))]'}`}>{conversation.lastMessage}</p></div>{conversation.unreadCount > 0 && <span data-testid={`badge-conversation-${conversation.id}`} className="flex h-6 min-w-6 items-center justify-center rounded-full bg-[hsl(var(--accent))] px-1.5 text-xs font-bold">{conversation.unreadCount}</span>}<ArrowRight size={16} className="shrink-0 text-[hsl(var(--muted-foreground))]" /></Link>) : <div data-testid="empty-conversations" className="rounded-2xl border border-dashed border-[hsl(var(--border))] bg-[hsl(var(--card)/.5)] px-6 py-16 text-center"><MessageCircle size={24} className="mx-auto text-[hsl(var(--muted-foreground))]" /><h2 className="mt-4 font-display text-2xl">No conversations found</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Try another name, handle, or message.</p></div>}</div><aside className="h-fit space-y-4"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center gap-2 text-sm font-bold"><ShieldCheck size={16} className="text-[hsl(var(--primary))]" /> Messages have guardrails</div><p className="mt-3 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">Seller chats are for licensed availability and pickup timing. Friends are for sharing experiences, not buying or selling outside Greenline.</p></div><div className="rounded-2xl border border-[hsl(var(--accent)/.4)] bg-[hsl(var(--accent)/.1)] p-5 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]"><p className="font-bold text-[hsl(var(--foreground))]">A private-by-design inbox</p><p className="mt-2">Your exact location is never shared in chat. Block or report from any conversation if something feels off.</p></div></aside></div></main>;
}

function ConversationView({ conversations, messages, markConversationRead, sendMessage }: { conversations: Conversation[]; messages: Message[]; markConversationRead: (id: string) => void; sendMessage: (conversationId: string, body: string) => void }) {
  const { conversationId } = useParams<{ conversationId: string }>();
  const conversation = conversations.find((item) => item.id === conversationId) ?? conversations[0];
  const [body, setBody] = useState('');
  const [reported, setReported] = useState(false);
  const [blocked, setBlocked] = useState(false);
  useEffect(() => { markConversationRead(conversation.id); }, [conversation.id]);
  const thread = messages.filter((message) => message.conversationId === conversation.id);
   const quickReplies = conversation.kind === 'seller' ? ['Do you offer delivery?', 'What is the delivery charge?', 'Is pickup still available?', 'Can you confirm the window?'] : ['Thanks for sharing this.', 'I had a similar experience.', 'Want to compare notes?'];
  const submit = () => { if (body.trim() && !blocked) { sendMessage(conversation.id, body.trim()); setBody(''); } };
  return <main className="mx-auto flex min-h-[calc(100dvh-72px)] max-w-[1050px] flex-col px-5 pb-6 md:px-8"><div className="flex items-center gap-3 border-b border-[hsl(var(--border))] py-5"><Link href="/messages" data-testid="link-back-messages" aria-label="Back to messages" className="rounded-lg p-2 hover:bg-[hsl(var(--muted))]"><ArrowLeft size={18} /></Link><div className={`flex h-10 w-10 items-center justify-center rounded-xl text-xs font-bold ${conversation.kind === 'seller' ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]'}`}>{conversation.avatar}</div><div className="min-w-0"><div className="flex items-center gap-2 font-bold">{conversation.participantName}{conversation.participantVerified && <BadgeCheck size={14} className="text-[hsl(var(--primary))]" />}<span className="text-xs font-normal text-[hsl(var(--muted-foreground))]">{conversation.onlineStatus === 'online' ? 'Online' : conversation.onlineStatus === 'away' ? 'Away' : 'Offline'}</span></div><p className="truncate text-xs text-[hsl(var(--muted-foreground))]">{conversation.participantHandle} · {conversation.contextLabel}</p></div><div className="ml-auto flex items-center gap-1"><button data-testid="button-report-conversation" aria-label="Report conversation" onClick={() => setReported(true)} className="rounded-lg p-2 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]"><Flag size={16} /></button><button data-testid="button-block-conversation" aria-label={blocked ? 'Unblock conversation' : 'Block conversation'} onClick={() => setBlocked(!blocked)} className={`rounded-lg p-2 hover:bg-[hsl(var(--muted))] ${blocked ? 'text-[hsl(var(--destructive))]' : 'text-[hsl(var(--muted-foreground))]'}`}><Ban size={16} /></button></div></div>{reported && <div data-testid="status-report-message" role="status" className="mt-4 rounded-xl bg-[hsl(var(--muted))] p-3 text-xs">Report received. Our team will review the conversation. You can still leave at any time.</div>}<div className="flex-1 py-5"><div className={`mb-5 flex items-start gap-3 rounded-2xl p-4 ${conversation.kind === 'seller' ? 'bg-[hsl(var(--secondary))]' : 'bg-[hsl(var(--muted)/.65)]'}`}><div className="mt-0.5">{conversation.kind === 'seller' ? <Store size={17} className="text-[hsl(var(--primary))]" /> : <MessageCircle size={17} className="text-[hsl(var(--primary))]" />}</div><div><p className="text-xs font-bold">{conversation.kind === 'seller' ? 'Licensed seller conversation' : 'Community conversation'}</p><p className="mt-1 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">{conversation.kind === 'seller' ? 'Use this thread for product availability and pickup timing. Orders and payments stay in Greenline.' : 'Share experiences and local notes with care. Never arrange unlicensed sales or move transactions off-platform.'}</p></div></div><div className="space-y-3">{thread.map((message) => <div key={message.id} data-testid={`message-${message.id}`} className={`flex ${message.isMine ? 'justify-end' : 'justify-start'}`}><div className={`max-w-[82%] rounded-2xl px-4 py-3 ${message.isMine ? 'rounded-br-md bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'rounded-bl-md bg-[hsl(var(--muted))]'}`}><p className="text-sm leading-relaxed">{message.body}</p><div className={`mt-1.5 text-[10px] ${message.isMine ? 'text-[hsl(var(--primary-foreground)/.6)]' : 'text-[hsl(var(--muted-foreground))]'}`}>{message.sentAt}{message.isMine && ` · ${message.status}`}</div></div></div>)}</div></div><div className="border-t border-[hsl(var(--border))] pt-4"><div className="mb-3 flex gap-2 overflow-x-auto">{quickReplies.map((reply) => <button key={reply} data-testid={`button-quick-reply-${reply.slice(0, 5).replaceAll(' ', '-')}`} onClick={() => setBody(reply)} className="shrink-0 rounded-full border border-[hsl(var(--border))] px-3 py-1.5 text-[11px] font-semibold text-[hsl(var(--muted-foreground))] hover:border-[hsl(var(--primary))] hover:text-[hsl(var(--primary))]">{reply}</button>)}</div><div className="flex gap-2"><input data-testid="input-message-composer" aria-label={`Message ${conversation.participantName}`} disabled={blocked} value={body} onChange={(e) => setBody(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') submit(); }} placeholder={blocked ? 'Conversation blocked' : `Message ${conversation.participantName}`} className="h-11 flex-1 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 text-sm outline-none focus:border-[hsl(var(--primary))] disabled:opacity-50" /><button data-testid="button-send-message" disabled={!body.trim() || blocked} onClick={submit} className="flex h-11 w-11 items-center justify-center rounded-xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] opacity-50 enabled:opacity-100"><Send size={17} /></button></div><p className="mt-3 text-center text-[11px] text-[hsl(var(--muted-foreground))]">Your exact location is never shared in chat. Greenline does not support off-platform or unlicensed sales.</p></div></main>;
}

function BuyerStorefront({ products, sellers, sellerStores, memberships, favorites, toggleFavorite, addToBag, toggleMembership, toggleStoreNotifications, openSellerConversation }: { products: Product[]; sellers: Seller[]; sellerStores: SellerStore[]; memberships: Membership[]; favorites: string[]; toggleFavorite: (id: string) => void; addToBag: (id: string) => void; toggleMembership: (sellerId: string) => void; toggleStoreNotifications: (sellerId: string) => void; openSellerConversation: (placeName: string, initialMessage?: string) => void }) {
  const { sellerId } = useParams<{ sellerId: string }>();
  const seller = sellers.find((item) => item.id === sellerId) ?? sellers[0];
  const store = sellerStores.find((item) => item.sellerId === seller.id);
  const member = memberships.find((item) => item.sellerId === seller.id);
  const discoverable = seller.licenseStatus === 'Verified' && store?.planStatus === 'active';
  const catalog = products.filter((product) => product.seller === seller.name && product.sellerVerified && herbCategories.includes(product.category));
  if (!discoverable) return <main className="mx-auto max-w-3xl px-5 py-16 text-center md:px-8"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[hsl(var(--muted))]"><ShieldCheck size={25} className="text-[hsl(var(--muted-foreground))]" /></div><h1 className="mt-5 font-display text-4xl">This storefront is not public yet.</h1><p className="mx-auto mt-3 max-w-lg text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">Greenline only makes licensed, verified sellers with an active storefront rental discoverable. Demo license and billing states are shown here for clarity.</p><Link href="/discover" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-sm font-bold text-[hsl(var(--primary-foreground))]"><ArrowLeft size={16} /> Back to discover</Link></main>;
   return <main className="mx-auto max-w-[1180px] px-5 pb-16 md:px-8"><div className="relative overflow-hidden rounded-b-[30px] border-x border-b border-[hsl(var(--border))] bg-[hsl(var(--secondary))] p-6 md:p-10"><div className="absolute -right-20 -top-28 h-72 w-72 rounded-full border-[26px] border-[hsl(var(--primary)/.08)]" /><div className="relative flex flex-col justify-between gap-6 md:flex-row md:items-end"><div><Link href="/discover" className="mb-7 inline-flex items-center gap-2 text-xs font-bold text-[hsl(var(--muted-foreground))]"><ArrowLeft size={14} /> Discover licensed places</Link><div className="flex items-center gap-3"><div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-[hsl(var(--primary))] font-display text-xl text-[hsl(var(--primary-foreground))]">{seller.name.slice(0, 2)}</div><div><div className="flex items-center gap-2"><h1 className="font-display text-4xl tracking-[-.05em]">{store?.storefrontName ?? seller.name}</h1><BadgeCheck size={19} className="text-[hsl(var(--primary))]" /></div><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{seller.location} · {seller.licenseNumber}</p></div></div><p className="mt-5 max-w-xl text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">A licensed neighborhood storefront for herb and herb-related products. Demo availability only; confirm labels and pickup details with the seller.</p></div><div className="flex flex-wrap gap-2"><button data-testid="button-follow-store" onClick={() => toggleMembership(seller.id)} className={`flex items-center gap-2 rounded-xl px-4 py-3 text-sm font-bold ${member ? 'border border-[hsl(var(--border))] bg-[hsl(var(--card))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]'}`}><Users size={16} /> {member ? 'Following' : 'Join store'}</button><button data-testid="button-message-store" onClick={() => openSellerConversation(seller.name)} className="flex items-center gap-2 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 py-3 text-sm font-bold"><MessageCircle size={16} /> Message</button></div></div></div><div className="mt-6 grid gap-4 sm:grid-cols-3"><StatCard label="Followers" value={String(store?.followerCount ?? 0)} note={member ? `Joined ${member.joinedAt}` : 'Join for pickup updates'} tone="accent" /><StatCard label="Catalog" value={String(catalog.length)} note="Herb-only listings" /><StatCard label="License" value={seller.licenseStatus} note="Verified for discovery" tone="dark" /></div><div className="mt-6 flex flex-col gap-4 rounded-2xl border border-[hsl(var(--primary)/.2)] bg-[hsl(var(--card))] p-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Truck size={18} /></span><div><p className="font-semibold">{store?.deliveryEnabled ? 'Delivery available' : 'Pickup only'}</p><p className="mt-1 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">{store?.deliveryEnabled ? `$${store.deliveryFee.toFixed(2)} delivery · ${store.deliveryRadius} · usually ${store.deliveryEta}` : 'This seller currently lists pickup windows only.'}</p></div></div><button data-testid="button-ask-delivery-store" onClick={() => openSellerConversation(seller.name, 'Do you offer delivery to my area, and what is the delivery charge?')} className="flex items-center justify-center gap-2 rounded-xl border border-[hsl(var(--border))] px-3 py-2.5 text-xs font-bold"><MessageCircle size={15} /> Ask about delivery</button></div><div className="mt-8 flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-[.15em] text-[hsl(var(--primary))]">Store catalog</p><h2 className="mt-1 font-display text-3xl">What is on the shelf.</h2></div>{member && <button data-testid="button-toggle-store-notifications" onClick={() => toggleStoreNotifications(seller.id)} className="flex items-center gap-2 rounded-xl border border-[hsl(var(--border))] px-3 py-2 text-xs font-bold"><Bell size={14} /> {member.notificationsEnabled ? 'Pickup alerts on' : 'Pickup alerts off'}</button>}</div><div className="mt-5 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{catalog.map((product) => <ProductCard key={product.id} product={product} favorite={favorites.includes(product.id)} toggleFavorite={toggleFavorite} addToBag={addToBag} />)}</div>{!catalog.length && <div className="mt-5 rounded-2xl border border-dashed border-[hsl(var(--border))] p-12 text-center text-sm text-[hsl(var(--muted-foreground))]">This verified store has no herb listings in the demo catalog yet.</div>}</main>;
}

function SellerOnboarding({ sellerStore, storePlans, selectPlan, activateStorefront }: { sellerStore: SellerStore; storePlans: StorePlan[]; selectPlan: (planId: string) => void; activateStorefront: () => void }) {
  const [license, setLicense] = useState('CA-LIC-42918');
  const [storefrontName, setStorefrontName] = useState(sellerStore.storefrontName);
  const [acknowledged, setAcknowledged] = useState(false);
  const selectedPlan = storePlans.find((plan) => plan.id === sellerStore.planId) ?? storePlans[0];
  const canActivate = Boolean(license.trim() && storefrontName.trim() && acknowledged && sellerStore.planStatus !== 'active');
  return <OpsPage eyebrow="Seller workspace / setup" title="Open your Greenline storefront." detail="A short compliance-first setup for licensed sellers. Billing and license verification are demo states for now." action={<div className={`rounded-xl px-3 py-2 text-xs font-bold ${sellerStore.planStatus === 'active' ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}`}>{sellerStore.planStatus === 'active' ? 'Storefront active' : 'Setup in progress'}</div>}><div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><div className="space-y-5"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-sm font-bold">01</span><div><h2 className="font-semibold">Seller application</h2><p className="text-xs text-[hsl(var(--muted-foreground))]">Tell Greenline which licensed storefront to publish.</p></div></div><label className="mt-6 block text-xs font-bold uppercase tracking-wider">Storefront name<input data-testid="input-onboarding-store-name" value={storefrontName} onChange={(e) => setStorefrontName(e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3 text-sm outline-none" /></label><label className="mt-4 block text-xs font-bold uppercase tracking-wider">License number<input data-testid="input-onboarding-license" value={license} onChange={(e) => setLicense(e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3 text-sm outline-none" /></label><div className="mt-4 flex items-start gap-3 rounded-xl bg-[hsl(var(--muted))] p-3 text-xs"><ShieldCheck size={16} className="mt-0.5 shrink-0 text-[hsl(var(--primary))]" /><span><strong>Current demo status:</strong> {sellerStore.licenseStatus}. Real licensing verification will be connected later.</span></div></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-sm font-bold">02</span><div><h2 className="font-semibold">Catalog acknowledgement</h2><p className="text-xs text-[hsl(var(--muted-foreground))]">Every listing must fit Greenline’s herb-only model.</p></div></div><div className="mt-5 flex flex-wrap gap-2">{herbCategories.map((category) => <span key={category} className="rounded-full bg-[hsl(var(--secondary))] px-3 py-1.5 text-xs font-bold">{category}</span>)}</div><label className="mt-5 flex items-start gap-3 text-sm"><input data-testid="checkbox-onboarding-herb-only" type="checkbox" checked={acknowledged} onChange={(e) => setAcknowledged(e.currentTarget.checked)} className="mt-0.5 h-4 w-4 accent-[hsl(var(--primary))]" /><span>I will only publish herb and herb-related products in the six approved categories.</span></label></div></div><div className="h-fit rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.15em] text-[hsl(var(--primary))]">03 · Rental</p><h2 className="mt-1 font-display text-3xl">Choose a storefront plan.</h2></div><WalletCards size={21} className="text-[hsl(var(--primary))]" /></div><div className="mt-5 space-y-3">{storePlans.map((plan) => <button key={plan.id} data-testid={`button-onboarding-plan-${plan.id}`} onClick={() => selectPlan(plan.id)} className={`w-full rounded-xl border p-4 text-left ${selectedPlan.id === plan.id ? 'border-[hsl(var(--primary))] bg-[hsl(var(--secondary))]' : 'border-[hsl(var(--border))]'}`}><div className="flex items-center justify-between"><span className="font-bold">{plan.name}</span><span className="font-mono-ui text-sm">${plan.monthlyPrice}/mo</span></div><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{plan.listingLimit ? `${plan.listingLimit} listings` : 'Unlimited listings'} · {plan.description}</p></button>)}</div><button data-testid="button-activate-onboarding-store" disabled={!canActivate} onClick={activateStorefront} className="mt-5 w-full rounded-xl bg-[hsl(var(--primary))] py-3 text-sm font-bold text-[hsl(var(--primary-foreground))] opacity-50 enabled:opacity-100">{sellerStore.planStatus === 'active' ? 'Storefront is active' : 'Activate demo rental'}</button><p className="mt-4 text-center text-[11px] text-[hsl(var(--muted-foreground))]">Demo billing only. No payment is processed.</p></div></div></OpsPage>;
}

function SellerStoreManagement({ sellerStore, storePlans, sellers, activateStorefront, cancelStorefront, updateSellerDelivery }: { sellerStore: SellerStore; storePlans: StorePlan[]; sellers: Seller[]; activateStorefront: () => void; cancelStorefront: () => void; updateSellerDelivery: (changes: Partial<Pick<SellerStore, 'deliveryEnabled' | 'deliveryFee' | 'deliveryRadius' | 'deliveryEta'>>) => void }) {
  const seller = sellers.find((item) => item.id === sellerStore.sellerId) ?? sellers[0];
  const plan = storePlans.find((item) => item.id === sellerStore.planId) ?? storePlans[0];
  const eligible = sellerStore.planStatus === 'active' && sellerStore.licenseStatus === 'Verified';
  return <OpsPage eyebrow="Seller workspace / storefront" title={sellerStore.storefrontName} detail="Manage the public storefront, follower relationship, and publishing eligibility." action={<Link href={`/store/${sellerStore.sellerId}`} data-testid="link-public-store-preview" className="flex items-center gap-2 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 py-2.5 text-sm font-bold"><Globe2 size={16} /> Public preview</Link>}><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.15em] text-[hsl(var(--primary))]">Public storefront</p><h2 className="mt-2 font-display text-4xl">{sellerStore.storefrontName}</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">{seller.location} · Licensed herb marketplace</p></div><div className={`rounded-full px-3 py-1.5 text-[11px] font-bold ${eligible ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}`}>{eligible ? 'Discoverable' : 'Not discoverable'}</div></div><div className="mt-8 grid grid-cols-3 gap-3"><StatCard label="Followers" value={String(sellerStore.followerCount)} note="Local members" /><StatCard label="Listings" value={String(sellerStore.productCount)} note={plan.listingLimit ? `of ${plan.listingLimit}` : 'Unlimited'} /><StatCard label="License" value={seller.licenseStatus} note="Compliance state" /></div><div className="mt-6 rounded-xl bg-[hsl(var(--muted))] p-4 text-xs leading-relaxed"><span className="font-bold">Eligibility rule:</span> only verified sellers with an active rental plan can appear in buyer discovery or publish products. Current result: <strong>{eligible ? 'eligible' : 'paused'}.</strong></div></div><div className="space-y-4"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.15em] text-[hsl(var(--primary))]">Current plan</p><h2 className="mt-1 font-display text-3xl">{plan.name}</h2></div><WalletCards size={20} className="text-[hsl(var(--primary))]" /></div><p className="mt-3 text-sm text-[hsl(var(--muted-foreground))]">${plan.monthlyPrice}/month · {plan.listingLimit ? `${plan.listingLimit} listings` : 'unlimited listings'}</p><div className="mt-5 flex gap-2"><Link href="/seller/plan" className="flex-1 rounded-xl bg-[hsl(var(--primary))] py-2.5 text-center text-xs font-bold text-[hsl(var(--primary-foreground))]">Manage plan</Link>{sellerStore.planStatus === 'active' && <button data-testid="button-cancel-storefront" onClick={cancelStorefront} className="rounded-xl border border-[hsl(var(--border))] px-3 py-2.5 text-xs font-bold">Cancel</button>}{sellerStore.planStatus !== 'active' && <button data-testid="button-activate-storefront" onClick={activateStorefront} className="rounded-xl bg-[hsl(var(--accent))] px-3 py-2.5 text-xs font-bold text-[hsl(var(--accent-foreground))]">Activate</button>}</div></div><div className="rounded-2xl border border-[hsl(var(--accent)/.4)] bg-[hsl(var(--accent)/.1)] p-5 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]"><p className="font-bold text-[hsl(var(--foreground))]">Demo billing + compliance</p><p className="mt-2">No payment is processed and no license is verified in this prototype. Those connections come later.</p></div></div></div></OpsPage>;
}

function SellerPlanPage({ sellerStore, storePlans, selectStorePlan, activateStorefront, cancelStorefront }: { sellerStore: SellerStore; storePlans: StorePlan[]; selectStorePlan: (planId: string) => void; activateStorefront: () => void; cancelStorefront: () => void }) {
  const [confirmPlan, setConfirmPlan] = useState<string | null>(null);
  const current = storePlans.find((plan) => plan.id === sellerStore.planId) ?? storePlans[0];
  const chosen = storePlans.find((plan) => plan.id === confirmPlan);
  return <OpsPage eyebrow="Seller workspace / rental" title="Rent the right storefront." detail="Compare monthly demo plans. A rental makes a verified seller eligible to publish a compliant catalog." action={<div className={`flex items-center gap-2 rounded-xl px-3 py-2 text-xs font-bold ${sellerStore.planStatus === 'active' ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}`}><WalletCards size={14} /> {current.name} · {sellerStore.planStatus}</div>}><div className="grid gap-4 lg:grid-cols-3">{storePlans.map((plan) => <div key={plan.id} data-testid={`card-store-plan-${plan.id}`} className={`relative rounded-2xl border bg-[hsl(var(--card))] p-6 ${plan.featured ? 'border-[hsl(var(--primary))] shadow-[0_12px_30px_hsl(var(--primary)/.1)]' : 'border-[hsl(var(--border))]'}`}>{plan.featured && <span className="absolute right-4 top-4 rounded-full bg-[hsl(var(--accent))] px-2.5 py-1 text-[10px] font-bold">Most useful</span>}<p className="text-xs font-bold uppercase tracking-[.15em] text-[hsl(var(--primary))]">{plan.name}</p><div className="mt-4 flex items-end gap-1"><span className="font-mono-ui text-4xl">${plan.monthlyPrice}</span><span className="mb-1 text-xs text-[hsl(var(--muted-foreground))]">/ month</span></div><p className="mt-3 min-h-10 text-sm text-[hsl(var(--muted-foreground))]">{plan.description}</p><div className="my-5 space-y-3 border-y border-[hsl(var(--border))] py-4 text-xs"><p className="flex items-center gap-2"><Check size={15} className="text-[hsl(var(--primary))]" /> {plan.listingLimit ? `${plan.listingLimit} herb listings` : 'Unlimited herb listings'}</p><p className="flex items-center gap-2"><Check size={15} className="text-[hsl(var(--primary))]" /> Public storefront preview</p><p className="flex items-center gap-2"><Check size={15} className="text-[hsl(var(--primary))]" /> Follower updates + seller messages</p></div><button data-testid={`button-select-plan-${plan.id}`} onClick={() => setConfirmPlan(plan.id)} className={`w-full rounded-xl py-3 text-xs font-bold ${current.id === plan.id ? 'border border-[hsl(var(--border))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]'}`}>{current.id === plan.id ? 'Current plan' : 'Choose plan'}</button></div>)}</div><div className="mt-7 overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="border-b border-[hsl(var(--border))] p-5"><h2 className="font-semibold">Plan comparison</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">A quick view of the demo rental model.</p></div><div className="grid grid-cols-4 gap-3 p-5 text-xs"><span className="font-bold">Feature</span>{storePlans.map((plan) => <span key={plan.id} className="font-bold">{plan.name}</span>)}<span className="text-[hsl(var(--muted-foreground))]">Listing cap</span>{storePlans.map((plan) => <span key={plan.id}>{plan.listingLimit ?? 'Unlimited'}</span>)}<span className="text-[hsl(var(--muted-foreground))]">Discovery eligibility</span>{storePlans.map((plan) => <span key={plan.id}>Verified sellers</span>)}</div></div><div className="mt-5 flex flex-wrap items-center justify-between gap-3 rounded-2xl bg-[hsl(var(--secondary))] p-5 text-sm"><p><strong>Rental status:</strong> {sellerStore.planStatus === 'active' ? 'Your store can publish.' : 'Your catalog is paused until activation.'}</p><div className="flex gap-2">{sellerStore.planStatus === 'active' && <button data-testid="button-cancel-plan" onClick={cancelStorefront} className="rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 py-2.5 text-xs font-bold">Cancel demo rental</button>}{sellerStore.planStatus !== 'active' && <button data-testid="button-activate-plan" onClick={activateStorefront} className="rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-xs font-bold text-[hsl(var(--primary-foreground))]">Activate selected rental</button>}</div></div>{chosen && <div className="fixed inset-0 z-50 flex items-center justify-center bg-[hsl(var(--foreground)/.48)] p-5"><div className="w-full max-w-md rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6 shadow-2xl"><h2 className="font-display text-3xl">{chosen.name} storefront rental</h2><p className="mt-3 text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">Switch the demo rental to ${chosen.monthlyPrice}/month? This changes listing eligibility locally; no payment will be processed.</p><div className="mt-6 flex gap-2"><button data-testid="button-cancel-plan-confirmation" onClick={() => setConfirmPlan(null)} className="flex-1 rounded-xl border border-[hsl(var(--border))] py-3 text-sm font-bold">Keep current</button><button data-testid="button-confirm-plan" onClick={() => { selectStorePlan(chosen.id); setConfirmPlan(null); }} className="flex-1 rounded-xl bg-[hsl(var(--primary))] py-3 text-sm font-bold text-[hsl(var(--primary-foreground))]">Confirm change</button></div></div></div>}</OpsPage>;
}

function AgeGate({ onConfirm }: { onConfirm: () => void }) {
  const [confirmed, setConfirmed] = useState(false);
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[hsl(var(--foreground)/.56)] p-5 backdrop-blur-sm"><div className="w-full max-w-md rounded-[26px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-7 shadow-2xl"><div className="mb-6 flex h-12 w-12 items-center justify-center rounded-2xl bg-[hsl(var(--primary))] text-[hsl(var(--accent))]"><Leaf size={23} /></div><p className="mb-2 text-xs font-bold uppercase tracking-[.16em] text-[hsl(var(--primary))]">Welcome to Greenline</p><h2 className="font-display text-4xl leading-none tracking-[-.04em]">A marketplace for adults.</h2><p className="mt-4 text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">You must be 21 or older to browse cannabis products. Greenline only works with licensed sellers in your jurisdiction.</p><label className="mt-6 flex cursor-pointer items-start gap-3 rounded-xl border border-[hsl(var(--border))] p-3.5 text-sm"><input data-testid="checkbox-age-gate" type="checkbox" checked={confirmed} onChange={(event) => setConfirmed(event.currentTarget.checked)} className="mt-0.5 h-4 w-4 accent-[hsl(var(--primary))]" /><span>I confirm I am 21 or older and shopping within a permitted jurisdiction.</span></label><button data-testid="button-confirm-age" disabled={!confirmed} onClick={onConfirm} className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-3.5 text-sm font-bold text-[hsl(var(--primary-foreground))] opacity-50 enabled:opacity-100">Enter Greenline <ArrowRight size={16} /></button><p className="mt-4 text-center text-[11px] text-[hsl(var(--muted-foreground))]">By entering, you agree to shop responsibly and follow local laws.</p></div></div>;
}

function ProductCard({ product, favorite, toggleFavorite, addToBag }: { product: Product; favorite: boolean; toggleFavorite: (id: string) => void; addToBag: (id: string) => void }) {
  return <article data-testid={`card-product-${product.id}`} className="group overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] shadow-[0_8px_24px_hsl(var(--foreground)/.035)] hover:-translate-y-0.5 hover:shadow-[0_12px_28px_hsl(var(--foreground)/.08)]"><div className={`relative h-52 overflow-hidden product-art-${product.image}`}><div className="absolute left-4 top-4 rounded-full bg-[hsl(var(--card)/.82)] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.12em] backdrop-blur">{product.category}</div><button data-testid={`button-favorite-${product.id}`} aria-label={favorite ? `Remove ${product.name} from favorites` : `Save ${product.name}`} onClick={() => toggleFavorite(product.id)} className="absolute right-3 top-3 rounded-full bg-[hsl(var(--card)/.8)] p-2 backdrop-blur hover:scale-105">{favorite ? <Heart size={16} fill="hsl(var(--accent))" className="text-[hsl(var(--accent-foreground))]" /> : <Heart size={16} />}</button><div className="absolute bottom-4 left-4 font-display text-3xl text-[hsl(var(--foreground)/.75)]">{product.image === 'sunset' ? 'warm / bright' : product.image === 'mint' ? 'slow / steady' : product.image === 'tide' ? 'clear / lifted' : product.image === 'night' ? 'quiet / deep' : product.image === 'golden' ? 'easy / social' : 'soft / balanced'}</div></div><div className="p-4"><div className="flex items-start justify-between gap-3"><div><Link href={`/product/${product.id}`} data-testid={`link-product-${product.id}`} className="font-bold hover:text-[hsl(var(--primary))]">{product.name}</Link><p className="mt-1 flex items-center gap-1.5 text-xs text-[hsl(var(--muted-foreground))]"><Store size={12} /> {product.seller} <BadgeCheck size={13} className="text-[hsl(var(--primary))]" /></p></div><div className="text-right"><div className="font-mono-ui text-sm font-medium">{money(product.price)}</div><div className="text-[11px] text-[hsl(var(--muted-foreground))]">{product.unit}</div></div></div><div className="mt-4 flex items-center justify-between border-t border-[hsl(var(--border))] pt-3 text-xs"><span className="flex items-center gap-1 font-semibold"><Star size={13} fill="hsl(var(--accent))" className="text-[hsl(var(--accent-foreground))]" /> {product.rating} <span className="font-normal text-[hsl(var(--muted-foreground))]">({product.reviewCount})</span></span><span className={product.stockStatus === 'Low stock' ? 'font-semibold text-amber-700' : 'text-[hsl(var(--muted-foreground))]'}>{product.stockStatus}</span></div><button data-testid={`button-add-${product.id}`} onClick={() => addToBag(product.id)} disabled={product.stockStatus === 'Sold out'} className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-[hsl(var(--secondary))] py-2.5 text-sm font-bold hover:bg-[hsl(var(--primary))] hover:text-[hsl(var(--primary-foreground))] disabled:opacity-40"><Plus size={16} /> Add to bag</button></div></article>;
}

function EmptyState({ search, onClear }: { search: string; onClear: () => void }) {
  return <div data-testid="empty-products" className="mt-5 rounded-2xl border border-dashed border-[hsl(var(--border))] bg-[hsl(var(--card)/.5)] px-6 py-16 text-center"><Search size={25} className="mx-auto text-[hsl(var(--muted-foreground))]" /><h3 className="mt-4 font-display text-2xl">Nothing matched “{search}”</h3><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Try a different product or seller name.</p><button data-testid="button-clear-search" onClick={onClear} className="mt-5 rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-bold text-[hsl(var(--primary-foreground))]">Clear search</button></div>;
}

function TrustPill({ icon: Icon, title, text }: { icon: LucideIcon; title: string; text: string }) {
  return <div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4"><Icon size={18} className="text-[hsl(var(--primary))]" /><p className="mt-5 text-sm font-bold">{title}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{text}</p></div>;
}

function ProductDetail({ products, sellerStores, favorites, toggleFavorite, addToBag, bagCount, openSellerConversation }: { products: Product[]; sellerStores: SellerStore[]; favorites: string[]; toggleFavorite: (id: string) => void; addToBag: (id: string) => void; bagCount: number; openSellerConversation: (placeName: string, initialMessage?: string) => void }) {
  const { id } = useParams<{ id: string }>();
  const product = products.find((item) => item.id === id) ?? products[0];
   const sellerStore = sellerStores.find((store) => store.storefrontName === product.seller);
  const [quantity, setQuantity] = useState(1);
   return <main className="mx-auto max-w-[1120px] px-5 py-8 md:px-8 md:py-12"><Link href="/" data-testid="link-back-browse" className="mb-8 inline-flex items-center gap-2 text-sm font-semibold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]">← Back to browse</Link><div className="grid gap-10 md:grid-cols-[1fr_.85fr]"><div className={`relative min-h-[420px] overflow-hidden rounded-[28px] product-art-${product.image}`}><span className="absolute left-6 top-6 rounded-full bg-[hsl(var(--card)/.78)] px-3 py-1.5 text-xs font-bold uppercase tracking-[.12em] backdrop-blur">{product.category}</span><div className="absolute bottom-7 left-7 font-display text-5xl text-[hsl(var(--foreground)/.72)]">{product.name}</div></div><div className="flex flex-col justify-center"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.15em] text-[hsl(var(--primary))]"><BadgeCheck size={15} /> Verified listing</div><h1 className="mt-3 font-display text-5xl leading-none tracking-[-.05em]">{product.name}</h1><p className="mt-3 flex items-center gap-2 text-sm text-[hsl(var(--muted-foreground))]"><Store size={15} /> {product.seller} <span>·</span> <MapPin size={14} /> 1.4 mi away</p><div className="mt-7 flex items-end gap-3"><span className="font-mono-ui text-3xl">{money(product.price)}</span><span className="mb-1 text-sm text-[hsl(var(--muted-foreground))]">per {product.unit}</span></div><div className="mt-6 grid grid-cols-3 divide-x divide-[hsl(var(--border))] rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] py-4"><Metric label="THC" value={`${product.thc}%`} /><Metric label="CBD" value={`${product.cbd}%`} /><Metric label="Rating" value={`${product.rating} / 5`} /></div><div className="mt-6 rounded-2xl bg-[hsl(var(--muted))] p-4"><div className="flex items-center gap-2 text-sm font-bold"><Clock3 size={16} className="text-[hsl(var(--primary))]" /> Pickup ready today</div><p className="mt-1 pl-6 text-xs text-[hsl(var(--muted-foreground))]">{product.seller} · North Park · 1.4 mi</p></div><div className="mt-3 flex items-start gap-3 rounded-2xl border border-[hsl(var(--primary)/.2)] bg-[hsl(var(--card))] p-4"><Truck size={17} className="mt-0.5 shrink-0 text-[hsl(var(--primary))]" /><div className="min-w-0 flex-1"><p className="text-sm font-bold">{sellerStore?.deliveryEnabled ? 'Delivery may be available' : 'Ask about delivery'}</p><p className="mt-1 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">{sellerStore?.deliveryEnabled ? `Demo seller details show $${sellerStore.deliveryFee.toFixed(2)} delivery within ${sellerStore.deliveryRadius}. Confirm your exact charge with the seller.` : 'The seller has not published delivery details yet. Ask in chat before placing an order.'}</p></div><button data-testid="button-ask-delivery-product" onClick={() => openSellerConversation(product.seller, `Do you offer delivery for ${product.name}, and what is the delivery charge to my area?`)} className="shrink-0 rounded-xl bg-[hsl(var(--secondary))] px-3 py-2 text-xs font-bold"><MessageCircle size={14} className="mr-1 inline" /> Ask</button></div><div className="mt-6 flex gap-3"><div className="flex items-center rounded-xl border border-[hsl(var(--border))]"><button data-testid="button-decrease-quantity" onClick={() => setQuantity(Math.max(1, quantity - 1))} className="px-3 py-3 text-lg">−</button><span data-testid="text-quantity" className="w-7 text-center font-mono-ui text-sm">{quantity}</span><button data-testid="button-increase-quantity" onClick={() => setQuantity(quantity + 1)} className="px-3 py-3 text-lg">+</button></div><button data-testid="button-add-detail" onClick={() => Array.from({ length: quantity }).forEach(() => addToBag(product.id))} className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-sm font-bold text-[hsl(var(--primary-foreground))] hover:brightness-110"><ShoppingBag size={17} /> Add to bag {bagCount > 0 && `· ${bagCount}`}</button><button data-testid="button-favorite-detail" onClick={() => toggleFavorite(product.id)} aria-label="Save product" className="rounded-xl border border-[hsl(var(--border))] px-4 hover:bg-[hsl(var(--muted))]">{favorites.includes(product.id) ? <Heart fill="hsl(var(--accent))" /> : <Heart />}</button></div><p className="mt-4 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">Always start low and go slow. Product information is provided by the licensed seller and may vary by batch.</p></div></div></main>;
}
function Metric({ label, value }: { label: string; value: string }) { return <div className="text-center"><div className="font-mono-ui text-sm font-medium">{value}</div><div className="mt-1 text-[10px] font-bold uppercase tracking-[.12em] text-[hsl(var(--muted-foreground))]">{label}</div></div>; }

function OpsHeader({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: ReactNode }) {
  return <div className="flex flex-col justify-between gap-5 border-b border-[hsl(var(--border))] px-5 py-8 md:flex-row md:items-end md:px-9 md:py-10"><div><p className="mb-2 text-[11px] font-bold uppercase tracking-[.18em] text-[hsl(var(--primary))]">{eyebrow}</p><h1 className="font-display text-4xl tracking-[-.05em] md:text-5xl">{title}</h1><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">{detail}</p></div>{action}</div>;
}
function OpsPage({ children, ...props }: { children: ReactNode; eyebrow: string; title: string; detail: string; action?: ReactNode }) { return <div><OpsHeader {...props} /> <div className="px-5 py-7 md:px-9 md:py-9">{children}</div></div>; }
function StatCard({ label, value, note, tone = 'plain' }: { label: string; value: string; note: string; tone?: 'plain' | 'accent' | 'dark' }) { return <div className={`rounded-2xl border p-5 ${tone === 'accent' ? 'border-[hsl(var(--accent)/.4)] bg-[hsl(var(--accent)/.14)]' : tone === 'dark' ? 'border-[hsl(var(--primary))] bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'border-[hsl(var(--border))] bg-[hsl(var(--card))]'}`}><p className="text-xs font-semibold opacity-70">{label}</p><p className="mt-3 font-mono-ui text-3xl tracking-[-.05em]">{value}</p><p className="mt-2 text-xs opacity-65">{note}</p></div>; }
function SellerOverviewWithChat({ products, orders, updateOrder }: { products: Product[]; orders: Order[]; updateOrder: (id: string, status: Order['status']) => void }) {
  return <div className="relative"><SellerOverview products={products} orders={orders} updateOrder={updateOrder} /><Link href="/messages/seller-juniper" data-testid="link-message-juniper" className="fixed bottom-6 right-5 z-20 flex items-center gap-2 rounded-full bg-[hsl(var(--primary))] px-4 py-3 text-xs font-bold text-[hsl(var(--primary-foreground))] shadow-xl md:right-8"><MessageCircle size={15} /> Message Juniper House</Link></div>;
}

function SellerOverview({ products, orders, updateOrder }: { products: Product[]; orders: Order[]; updateOrder: (id: string, status: Order['status']) => void }) {
  return <OpsPage eyebrow="Seller workspace" title="Good morning, Juniper House." detail="Tuesday, October 24 · Your storefront is healthy." action={<Link href="/" data-testid="link-view-storefront" className="flex items-center gap-2 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 py-2.5 text-sm font-bold"><Store size={16} /> View storefront</Link>}><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Today’s sales" value="$1,248.60" note="+12.4% from last Tuesday" tone="dark" /><StatCard label="Open orders" value="12" note="3 need your attention" tone="accent" /><StatCard label="Active products" value={`${products.length + 36}`} note="2 low stock" /><StatCard label="Store rating" value="4.8" note="From 126 reviews" /></div><div className="mt-8 grid gap-5 xl:grid-cols-[1.4fr_.8fr]"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] p-5"><div><h2 className="font-semibold">Order queue</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">The next few pickups to prepare</p></div><Link href="/seller/orders" data-testid="link-see-all-orders" className="text-xs font-bold text-[hsl(var(--primary))]">See all <ArrowRight className="ml-1 inline" size={13} /></Link></div><div className="divide-y divide-[hsl(var(--border))]">{orders.slice(0, 3).map((order) => <OrderRow key={order.id} order={order} updateOrder={updateOrder} compact />)}</div></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Inventory pulse</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Items worth a look</p></div><Package size={18} className="text-[hsl(var(--primary))]" /></div><div className="mt-6 space-y-5"><InventoryPulse name="Low Tide Vape" count="4 units left" percent={18} /><InventoryPulse name="Night Garden Tincture" count="11 units left" percent={42} /><InventoryPulse name="Sunset Sherbet" count="26 units left" percent={74} /></div><Link href="/seller/products" data-testid="link-manage-inventory" className="mt-7 block rounded-xl bg-[hsl(var(--secondary))] py-2.5 text-center text-xs font-bold hover:bg-[hsl(var(--primary))] hover:text-[hsl(var(--primary-foreground))]">Manage inventory</Link></div></div></OpsPage>;
}
function InventoryPulse({ name, count, percent }: { name: string; count: string; percent: number }) { return <div><div className="flex justify-between text-sm"><span className="font-semibold">{name}</span><span className="font-mono-ui text-xs text-[hsl(var(--muted-foreground))]">{count}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className={`h-full rounded-full ${percent < 25 ? 'bg-amber-500' : 'bg-[hsl(var(--primary))]'}`} style={{ width: `${percent}%` }} /></div></div>; }

function SellerProducts({ products, updateProduct, addProduct, sellerStore, storePlans }: { products: Product[]; updateProduct: (id: string, changes: Partial<Product>) => void; addProduct: (changes: Partial<Product>) => void; sellerStore: SellerStore; storePlans: StorePlan[] }) {
  const plan = storePlans.find((item) => item.id === sellerStore.planId);
  if (sellerStore.planStatus !== 'active') return <OpsPage eyebrow="Seller workspace / inventory" title="Inventory is waiting on a storefront." detail="Listings become discoverable only after a licensed seller rents an active Greenline storefront plan." action={<Link href="/seller/plan" data-testid="link-rent-store-from-inventory" className="flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-bold text-[hsl(var(--primary-foreground))]"><WalletCards size={16} /> Rent a store</Link>}><div className="mx-auto max-w-2xl rounded-[26px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-7 text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Store size={25} /></div><h2 className="mt-5 font-display text-3xl">A storefront is your publishing key.</h2><p className="mt-3 text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">Your license can be reviewed while your catalog stays paused. Choose a monthly rental plan, then activate the demo rental to publish herb-only products.</p><div className="mt-6 grid gap-3 text-left sm:grid-cols-3"><div className="rounded-xl bg-[hsl(var(--muted))] p-3 text-xs"><ShieldCheck size={15} className="text-[hsl(var(--primary))]" /><p className="mt-2 font-bold">Licensed</p><p className="mt-1 text-[hsl(var(--muted-foreground))]">{sellerStore.licenseStatus}</p></div><div className="rounded-xl bg-[hsl(var(--muted))] p-3 text-xs"><WalletCards size={15} className="text-[hsl(var(--primary))]" /><p className="mt-2 font-bold">Plan</p><p className="mt-1 text-[hsl(var(--muted-foreground))]">{plan?.name ?? 'Not selected'}</p></div><div className="rounded-xl bg-[hsl(var(--muted))] p-3 text-xs"><Leaf size={15} className="text-[hsl(var(--primary))]" /><p className="mt-2 font-bold">Catalog</p><p className="mt-1 text-[hsl(var(--muted-foreground))]">Herb only</p></div></div><p className="mt-6 text-[11px] text-[hsl(var(--muted-foreground))]">Demo billing only. Real payments and licensing verification will be connected later.</p></div></OpsPage>;
  return <SellerProductsCore products={products} updateProduct={updateProduct} addProduct={addProduct} />;
}

function SellerProductsCore({ products, updateProduct, addProduct }: { products: Product[]; updateProduct: (id: string, changes: Partial<Product>) => void; addProduct: (changes: Partial<Product>) => void }) {
  const [query, setQuery] = useState('');
  const [editing, setEditing] = useState<string | null>(null);
  const filtered = products.filter((p) => `${p.name} ${p.category}`.toLowerCase().includes(query.toLowerCase()));
  return <OpsPage eyebrow="Seller workspace / inventory" title="Inventory" detail="Keep your catalog accurate, available, and easy to trust." action={<button data-testid="button-add-product" onClick={() => setEditing('new')} className="flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-bold text-[hsl(var(--primary-foreground))]"><Plus size={17} /> Add product</button>}><div className="mb-5 flex flex-col justify-between gap-3 md:flex-row md:items-center"><div className="relative max-w-sm flex-1"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[hsl(var(--muted-foreground))]" /><input aria-label="Search inventory" data-testid="input-inventory-search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search your products" className="h-10 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] pl-9 text-sm outline-none focus:border-[hsl(var(--primary))]" /></div><div className="flex gap-2 text-xs"><span className="rounded-full bg-[hsl(var(--secondary))] px-3 py-2 font-bold">{products.length} active</span><span className="rounded-full bg-amber-100 px-3 py-2 font-bold text-amber-800">{products.filter((p) => p.stockStatus === 'Low stock').length} low stock</span></div></div><div className="overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="hidden grid-cols-[1.5fr_.7fr_.6fr_.7fr_.6fr_48px] gap-4 border-b border-[hsl(var(--border))] bg-[hsl(var(--muted)/.55)] px-5 py-3 text-[10px] font-bold uppercase tracking-[.13em] text-[hsl(var(--muted-foreground))] md:grid"><span>Product</span><span>Category</span><span>Price</span><span>Stock</span><span>Status</span><span /></div>{filtered.map((product) => <div key={product.id} data-testid={`row-inventory-${product.id}`} className="grid gap-3 border-b border-[hsl(var(--border))] px-5 py-4 last:border-0 md:grid-cols-[1.5fr_.7fr_.6fr_.7fr_.6fr_48px] md:items-center md:gap-4"><div><div className="font-semibold">{product.name}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{product.unit} · {product.thc}% THC / {product.cbd}% CBD</div></div><div className="text-xs text-[hsl(var(--muted-foreground))] md:text-sm">{product.category}</div><div className="font-mono-ui text-sm">{money(product.price)}</div><div><div className="h-1.5 w-20 rounded-full bg-[hsl(var(--muted))]"><div className={`h-full rounded-full ${product.stockStatus === 'Low stock' ? 'bg-amber-500' : 'bg-[hsl(var(--primary))]'}`} style={{ width: product.stockStatus === 'Low stock' ? '26%' : '78%' }} /></div><span className="mt-1 block text-[11px] text-[hsl(var(--muted-foreground))]">{product.stockStatus}</span></div><span className={`w-fit rounded-full px-2 py-1 text-[10px] font-bold ${product.stockStatus === 'Low stock' ? 'bg-amber-100 text-amber-800' : 'bg-emerald-100 text-emerald-800'}`}>{product.stockStatus === 'Low stock' ? 'Review' : 'Live'}</span><button data-testid={`button-edit-${product.id}`} onClick={() => setEditing(product.id)} aria-label={`Edit ${product.name}`} className="rounded-lg p-2 hover:bg-[hsl(var(--muted))]"><Pencil size={15} /></button></div>)}</div>{editing && <ProductEditDialog product={editing === 'new' ? null : products.find((p) => p.id === editing) ?? null} onClose={() => setEditing(null)} onSave={(changes) => { if (editing !== 'new') updateProduct(editing, changes); else addProduct(changes); setEditing(null); }} />}</OpsPage>;
}
function ProductEditDialog({ product, onClose, onSave }: { product: Product | null; onClose: () => void; onSave: (changes: Partial<Product>) => void }) {
  const [name, setName] = useState(product?.name ?? 'Fresh batch');
  const [price, setPrice] = useState(String(product?.price ?? 30));
  const [stock, setStock] = useState<Product['stockStatus']>(product?.stockStatus ?? 'In stock');
  const [category, setCategory] = useState(product?.category && herbCategories.includes(product.category) ? product.category : 'Flower');
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[hsl(var(--foreground)/.48)] p-5"><div className="w-full max-w-md rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6 shadow-2xl"><div className="flex items-center justify-between"><h2 className="font-display text-3xl">{product ? 'Edit product' : 'Add product'}</h2><button data-testid="button-close-product-dialog" onClick={onClose} aria-label="Close"><X size={19} /></button></div><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{product?.name ?? 'Create a new listing with compliant product details.'}</p><div className="mt-5 rounded-xl bg-[hsl(var(--secondary))] p-3 text-xs text-[hsl(var(--muted-foreground))]"><span className="font-bold text-[hsl(var(--foreground))]">Herb-only catalog.</span> Greenline accepts Flower, Pre-rolls, Edibles, Vaporizers, Tinctures, and Accessories.</div><label className="mt-5 block text-xs font-bold uppercase tracking-wider">Category<select aria-label="Product category" data-testid="select-product-category" value={category} onChange={(e) => setCategory(e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3">{herbCategories.map((item) => <option key={item}>{item}</option>)}</select></label>{product ? <><label className="mt-4 block text-xs font-bold uppercase tracking-wider">Price<input aria-label="Product price" data-testid="input-product-price" value={price} onChange={(e) => setPrice(e.target.value)} type="number" className="mt-2 h-11 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3 outline-none focus:border-[hsl(var(--primary))]" /></label><label className="mt-4 block text-xs font-bold uppercase tracking-wider">Availability<select aria-label="Product availability" data-testid="select-product-stock" value={stock} onChange={(e) => setStock(e.target.value as Product['stockStatus'])} className="mt-2 h-11 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3"><option>In stock</option><option>Low stock</option><option>Sold out</option></select></label></> : <><label className="mt-4 block text-xs font-bold uppercase tracking-wider">Product name<input aria-label="New product name" data-testid="input-new-product-name" value={name} onChange={(e) => setName(e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3 outline-none focus:border-[hsl(var(--primary))]" /></label><label className="mt-4 block text-xs font-bold uppercase tracking-wider">Price<input aria-label="New product price" data-testid="input-new-product-price" value={price} onChange={(e) => setPrice(e.target.value)} type="number" className="mt-2 h-11 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3 outline-none focus:border-[hsl(var(--primary))]" /></label><label className="mt-4 block text-xs font-bold uppercase tracking-wider">Availability<select aria-label="New product availability" data-testid="select-new-product-stock" value={stock} onChange={(e) => setStock(e.target.value as Product['stockStatus'])} className="mt-2 h-11 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-3"><option>In stock</option><option>Low stock</option><option>Sold out</option></select></label></>}<button data-testid="button-save-product" onClick={() => onSave({ name, category, price: Number(price), stockStatus: stock })} className="mt-6 w-full rounded-xl bg-[hsl(var(--primary))] py-3 text-sm font-bold text-[hsl(var(--primary-foreground))]">Save changes</button></div></div>;
}

function SellerOrders({ orders, updateOrder }: { orders: Order[]; updateOrder: (id: string, status: Order['status']) => void }) {
  const [status, setStatus] = useState('All orders');
  const filtered = orders.filter((o) => status === 'All orders' || o.status === status);
  return <OpsPage eyebrow="Seller workspace / orders" title="Order queue" detail="Move each order through its pickup journey." action={<div className="flex items-center gap-2 rounded-xl bg-[hsl(var(--accent)/.18)] px-3 py-2 text-xs font-bold text-[hsl(var(--accent-foreground))]"><Clock3 size={15} /> Pickup hours · 10:00–20:00</div>}><div className="mb-5 flex gap-2 overflow-x-auto">{['All orders', 'New', 'Preparing', 'Ready', 'Completed'].map((item) => <button key={item} data-testid={`button-order-filter-${item.toLowerCase()}`} onClick={() => setStatus(item)} className={`shrink-0 rounded-full px-4 py-2 text-xs font-bold ${status === item ? 'bg-[hsl(var(--foreground))] text-[hsl(var(--background))]' : 'border border-[hsl(var(--border))] bg-[hsl(var(--card))] text-[hsl(var(--muted-foreground))]'}`}>{item}{item !== 'All orders' && <span className="ml-1.5 font-mono-ui">· {orders.filter((o) => o.status === item).length}</span>}</button>)}</div><div className="space-y-3">{filtered.map((order) => <OrderRow key={order.id} order={order} updateOrder={updateOrder} />)}</div>{!filtered.length && <div className="rounded-2xl border border-dashed p-14 text-center"><ClipboardList className="mx-auto text-[hsl(var(--muted-foreground))]" /><p className="mt-3 font-display text-2xl">No orders in this view</p></div>}</OpsPage>;
}
function OrderRow({ order, updateOrder, compact = false }: { order: Order; updateOrder: (id: string, status: Order['status']) => void; compact?: boolean }) {
  const next: Record<Order['status'], Order['status'] | null> = { New: 'Preparing', Preparing: 'Ready', Ready: 'Completed', Completed: null };
  return <div data-testid={`row-order-${order.id}`} className={`flex flex-col gap-4 p-5 ${compact ? '' : 'rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]'} md:flex-row md:items-center md:justify-between`}><div className="flex gap-4"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] font-mono-ui text-xs font-bold">{order.id.slice(-2)}</div><div><div className="flex items-center gap-2 font-semibold">{order.id}<StatusBadge status={order.status} /></div><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{order.items.join(' · ')}</p><p className="mt-2 flex items-center gap-1.5 text-xs"><Clock3 size={12} /> {order.pickupWindow} <span className="text-[hsl(var(--muted-foreground))]">· {order.createdAt}</span></p></div></div><div className="flex items-center gap-3 md:justify-end"><span className="font-mono-ui text-sm">{money(order.total)}</span>{next[order.status] && <button data-testid={`button-advance-order-${order.id}`} onClick={() => updateOrder(order.id, next[order.status] as Order['status'])} className="rounded-lg bg-[hsl(var(--primary))] px-3 py-2 text-xs font-bold text-[hsl(var(--primary-foreground))]">{next[order.status] === 'Preparing' ? 'Start preparing' : next[order.status] === 'Ready' ? 'Mark ready' : 'Complete pickup'}</button>}</div></div>;
}
function StatusBadge({ status }: { status: Order['status'] }) { return <span className={`rounded-full px-2 py-0.5 text-[10px] font-bold ${status === 'New' ? 'bg-amber-100 text-amber-800' : status === 'Preparing' ? 'bg-blue-100 text-blue-800' : status === 'Ready' ? 'bg-emerald-100 text-emerald-800' : 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]'}`}>{status}</span>; }

function AdminOverview({ sellers, orders, products }: { sellers: Seller[]; orders: Order[]; products: Product[] }) {
  return <OpsPage eyebrow="Admin console" title="Marketplace health" detail="A clear view of what needs attention across Greenline." action={<div className="flex items-center gap-2 text-xs font-semibold text-[hsl(var(--muted-foreground))]"><span className="h-2 w-2 rounded-full bg-emerald-500" /> Last synced just now</div>}><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Active sellers" value="18" note="16 verified · 2 pending" tone="dark" /><StatCard label="Orders today" value="47" note="+8.2% vs. last Tuesday" /><StatCard label="Gross marketplace sales" value="$3,842" note="Across 61 line items" tone="accent" /><StatCard label="Needs attention" value="4" note="2 sellers · 2 inventory flags" /></div><div className="mt-8 grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Marketplace activity</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">A rolling view of important events</p></div><button data-testid="button-activity-filter" className="rounded-lg p-2 hover:bg-[hsl(var(--muted))]"><Filter size={16} /></button></div><div className="mt-5 space-y-1">{activities.map((activity) => <ActivityRow key={activity.id} activity={activity} />)}</div></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><h2 className="font-semibold">Quick read</h2><div className="mt-5 space-y-4"><HealthLine label="Seller verification" value={`${sellers.filter((s) => s.licenseStatus === 'Verified').length} / ${sellers.length}`} detail="verified sellers" percent={82} /><HealthLine label="Orders within SLA" value="96.4%" detail="on time today" percent={96} /><HealthLine label="Catalog availability" value={`${products.filter((p) => p.stockStatus !== 'Sold out').length} / ${products.length}`} detail="listings live" percent={88} /></div><Link href="/admin/sellers" data-testid="link-review-sellers" className="mt-7 flex items-center justify-center gap-2 rounded-xl bg-[hsl(var(--secondary))] py-3 text-xs font-bold">Review seller queue <ArrowRight size={14} /></Link></div></div><div className="mt-5 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Live order pulse</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Across all licensed sellers</p></div><Link href="/admin/orders" data-testid="link-view-all-marketplace-orders" className="text-xs font-bold text-[hsl(var(--primary))]">View all <ArrowRight size={13} className="ml-1 inline" /></Link></div><div className="mt-5 grid gap-3 sm:grid-cols-4">{(['New', 'Preparing', 'Ready', 'Completed'] as Order['status'][]).map((item) => <div key={item} className="rounded-xl bg-[hsl(var(--muted)/.7)] p-4"><StatusBadge status={item} /><div className="mt-3 font-mono-ui text-2xl">{orders.filter((o) => o.status === item).length + (item === 'Completed' ? 32 : 0)}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">orders</div></div>)}</div></div></OpsPage>;
}
function ActivityRow({ activity }: { activity: Activity }) { const Icon = iconForActivity(activity.type); return <div data-testid={`activity-${activity.id}`} className="flex items-center gap-3 rounded-xl p-3 hover:bg-[hsl(var(--muted)/.6)]"><span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ${activity.status === 'attention' ? 'bg-amber-100 text-amber-800' : 'bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]'}`}><Icon size={16} /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{activity.title}</p><p className="truncate text-xs text-[hsl(var(--muted-foreground))]">{activity.description}</p></div><span className="shrink-0 text-[11px] text-[hsl(var(--muted-foreground))]">{activity.timestamp}</span></div>; }
function HealthLine({ label, value, detail, percent }: { label: string; value: string; detail: string; percent: number }) { return <div><div className="flex items-end justify-between"><div><div className="text-sm font-semibold">{label}</div><div className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{detail}</div></div><div className="font-mono-ui text-sm">{value}</div></div><div className="mt-2 h-2 rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full bg-[hsl(var(--primary))]" style={{ width: `${percent}%` }} /></div></div>; }

function AdminSellers({ sellers, updateSeller }: { sellers: Seller[]; updateSeller: (id: string, licenseStatus: Seller['licenseStatus']) => void }) {
  const queue = sellers.filter((s) => s.licenseStatus !== 'Verified');
  return <OpsPage eyebrow="Admin console / seller verification" title="Seller verification" detail="Review licenses before a storefront reaches the public marketplace." action={<div className="rounded-xl bg-amber-100 px-3 py-2 text-xs font-bold text-amber-800">{queue.length} need review</div>}><div className="mb-5 flex items-center gap-2 text-sm text-[hsl(var(--muted-foreground))]"><ShieldCheck size={17} className="text-[hsl(var(--primary))]" /> Verification queue <span className="font-mono-ui">· {sellers.length} total sellers</span></div><div className="space-y-3">{sellers.map((seller) => <div key={seller.id} data-testid={`row-seller-${seller.id}`} className="flex flex-col gap-5 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 md:flex-row md:items-center md:justify-between"><div className="flex items-center gap-4"><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[hsl(var(--secondary))] font-display text-xl text-[hsl(var(--primary))]">{seller.name.charAt(0)}</div><div><div className="flex flex-wrap items-center gap-2 font-semibold">{seller.name}<span className={`rounded-full px-2 py-0.5 text-[10px] font-bold ${seller.licenseStatus === 'Verified' ? 'bg-emerald-100 text-emerald-800' : seller.licenseStatus === 'Pending' ? 'bg-amber-100 text-amber-800' : 'bg-red-100 text-red-800'}`}>{seller.licenseStatus}</span></div><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{seller.location} · {seller.productCount} products · {seller.lastActive}</p><p className="mt-2 flex items-center gap-1.5 font-mono-ui text-[11px] text-[hsl(var(--muted-foreground))]"><ShieldCheck size={12} /> {seller.licenseNumber}</p></div></div><div className="flex items-center gap-3"><div className="mr-2 hidden text-right sm:block"><div className="flex items-center gap-1 text-sm font-semibold"><Star size={13} fill="hsl(var(--accent))" /> {seller.rating}</div><div className="text-[10px] text-[hsl(var(--muted-foreground))]">seller rating</div></div>{seller.licenseStatus !== 'Verified' ? <><button data-testid={`button-reject-seller-${seller.id}`} onClick={() => updateSeller(seller.id, 'Needs review')} className="rounded-xl border border-[hsl(var(--border))] px-3 py-2 text-xs font-bold hover:border-red-300 hover:text-red-700">Hold</button><button data-testid={`button-verify-seller-${seller.id}`} onClick={() => updateSeller(seller.id, 'Verified')} className="rounded-xl bg-[hsl(var(--primary))] px-3 py-2 text-xs font-bold text-[hsl(var(--primary-foreground))]">Verify seller</button></> : <button data-testid={`button-review-seller-${seller.id}`} onClick={() => updateSeller(seller.id, 'Needs review')} className="rounded-xl border border-[hsl(var(--border))] px-3 py-2 text-xs font-bold">Reopen review</button>}</div></div>)}</div></OpsPage>;
}

function AdminOrders({ orders, updateOrder }: { orders: Order[]; updateOrder: (id: string, status: Order['status']) => void }) {
  const [query, setQuery] = useState('');
  const filtered = orders.filter((o) => `${o.id} ${o.seller} ${o.status}`.toLowerCase().includes(query.toLowerCase()));
  return <OpsPage eyebrow="Admin console / marketplace" title="Order oversight" detail="Monitor fulfillment across every licensed seller." action={<label className="relative"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[hsl(var(--muted-foreground))]" /><input data-testid="input-order-search" aria-label="Search orders" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search order ID or seller" className="h-10 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] pl-9 pr-3 text-sm outline-none" /></label>}><div className="mb-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><StatCard label="Open" value="15" note="Across 7 sellers" tone="accent" /><StatCard label="Ready now" value="6" note="Pickup windows today" /><StatCard label="Avg. prep time" value="18m" note="Down 3 minutes" /><StatCard label="Exceptions" value="2" note="Need follow-up" /></div><div className="space-y-3">{filtered.map((order) => <div key={order.id} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="flex flex-col gap-3 border-b border-[hsl(var(--border))] p-5 md:flex-row md:items-center md:justify-between"><div><div className="flex items-center gap-2 font-semibold">{order.id} <StatusBadge status={order.status} /></div><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{order.seller} · {order.createdAt}</p></div><div className="flex items-center gap-3"><Truck size={17} className="text-[hsl(var(--primary))]" /><span className="text-xs font-semibold">{order.pickupWindow}</span><span className="font-mono-ui text-sm">{money(order.total)}</span></div></div><div className="flex flex-wrap items-center justify-between gap-3 px-5 py-3"><div className="text-xs text-[hsl(var(--muted-foreground))]">{order.items.join(' · ')}</div>{order.status !== 'Completed' && <button data-testid={`button-admin-advance-${order.id}`} onClick={() => updateOrder(order.id, order.status === 'New' ? 'Preparing' : order.status === 'Preparing' ? 'Ready' : 'Completed')} className="text-xs font-bold text-[hsl(var(--primary))]">Advance status <ArrowRight size={13} className="ml-1 inline" /></button>}</div></div>)}</div></OpsPage>;
}

function SocialSettings({ ageConfirmed, setAgeConfirmed, flash, locationSharing, setLocationSharing, locationPrecision, setLocationPrecision, messagePrivacy, setMessagePrivacy }: { ageConfirmed: boolean; setAgeConfirmed: (value: boolean) => void; flash: (message: string) => void; locationSharing: boolean; setLocationSharing: (value: boolean) => void; locationPrecision: 'neighborhood' | 'approximate'; setLocationPrecision: (value: 'neighborhood' | 'approximate') => void; messagePrivacy: 'everyone' | 'connections'; setMessagePrivacy: (value: 'everyone' | 'connections') => void }) {
  return <div><SocialSettingsCore ageConfirmed={ageConfirmed} setAgeConfirmed={setAgeConfirmed} flash={flash} locationSharing={locationSharing} setLocationSharing={setLocationSharing} locationPrecision={locationPrecision} setLocationPrecision={setLocationPrecision} /><div className="mx-auto -mt-8 max-w-[980px] px-5 pb-12 md:px-8"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><div className="flex items-center gap-2 font-semibold"><MessageCircle size={17} className="text-[hsl(var(--primary))]" /> Who can message you</div><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Control incoming community messages. Seller conversations remain available for licensed pickup context.</p></div><div className="flex gap-2"><button data-testid="button-message-privacy-everyone" onClick={() => { setMessagePrivacy('everyone'); flash('Anyone in the community can message you'); }} className={`rounded-lg px-3 py-2 text-xs font-bold ${messagePrivacy === 'everyone' ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'border border-[hsl(var(--border))]'}`}>Everyone</button><button data-testid="button-message-privacy-connections" onClick={() => { setMessagePrivacy('connections'); flash('Only people you follow can message you'); }} className={`rounded-lg px-3 py-2 text-xs font-bold ${messagePrivacy === 'connections' ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'border border-[hsl(var(--border))]'}`}>Connections</button></div></div></div></div></div>;
}

function SocialSettingsCore({ ageConfirmed, setAgeConfirmed, flash, locationSharing, setLocationSharing, locationPrecision, setLocationPrecision }: { ageConfirmed: boolean; setAgeConfirmed: (value: boolean) => void; flash: (message: string) => void; locationSharing: boolean; setLocationSharing: (value: boolean) => void; locationPrecision: 'neighborhood' | 'approximate'; setLocationPrecision: (value: 'neighborhood' | 'approximate') => void }) {
  return <main className="mx-auto max-w-[980px] px-5 pb-16 md:px-8"><div className="flex flex-col justify-between gap-4 border-b border-[hsl(var(--border))] py-8 md:flex-row md:items-end"><div><p className="text-xs font-bold uppercase tracking-[.17em] text-[hsl(var(--primary))]">Account and privacy</p><h1 className="mt-2 font-display text-5xl tracking-[-.05em]">Your Greenline settings.</h1><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Control what you share, what you see, and where the marketplace applies.</p></div><button data-testid="button-save-social-settings" onClick={() => flash('Settings saved')} className="rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-bold text-[hsl(var(--primary-foreground))]">Save changes</button></div><div className="mt-8 grid gap-5 md:grid-cols-[.75fr_1.25fr]"><div><h2 className="font-semibold">Trust and control</h2><p className="mt-1 text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">Greenline is built to be local without making you public.</p></div><div className="space-y-3"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><ShieldCheck size={18} /></span><div><p className="font-semibold">Age verification</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{ageConfirmed ? 'Verified for this device · 21+ confirmed' : 'Required before browsing community content'}</p></div><button data-testid="button-settings-age" onClick={() => { setAgeConfirmed(!ageConfirmed); flash(ageConfirmed ? 'Age verification removed' : 'Age verified'); }} className={`ml-auto rounded-full px-3 py-1.5 text-xs font-bold ${ageConfirmed ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}`}>{ageConfirmed ? 'Verified' : 'Verify'}</button></div></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-start gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><LocateFixed size={18} /></span><div className="flex-1"><p className="font-semibold">Location sharing</p><p className="mt-1 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">Use approximate location to sort nearby licensed places. Precise coordinates stay on your device and are never published.</p><div className="mt-4 flex flex-wrap gap-2"><button data-testid="button-settings-location" onClick={() => { setLocationSharing(!locationSharing); flash(locationSharing ? 'Location sharing turned off' : 'Approximate location sharing turned on'); }} className={`rounded-xl px-3 py-2 text-xs font-bold ${locationSharing ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'bg-[hsl(var(--secondary))]'}`}>{locationSharing ? 'Sharing approximate location' : 'Keep location private'}</button><button data-testid="button-settings-precision" onClick={() => setLocationPrecision(locationPrecision === 'neighborhood' ? 'approximate' : 'neighborhood')} className="rounded-xl border border-[hsl(var(--border))] px-3 py-2 text-xs font-bold">Precision: {locationPrecision}</button></div></div></div></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><MapPin size={18} /></span><div><p className="font-semibold">Shopping jurisdiction</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">California · licensed listings only</p></div><span className="ml-auto rounded-full bg-[hsl(var(--muted))] px-2.5 py-1 text-[10px] font-bold">Protected</span></div></div><div className="rounded-2xl border border-[hsl(var(--accent)/.42)] bg-[hsl(var(--accent)/.12)] p-4 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]"><div className="flex items-center gap-2 font-bold text-[hsl(var(--foreground))]"><Globe2 size={15} /> Demo data notice</div><p className="mt-2">Places, product counts, and community activity are local prototype data. Greenline only displays verified sellers and licensed pickup points.</p></div></div></div></main>;
}

function SettingsPage({ ageConfirmed, setAgeConfirmed, flash }: { ageConfirmed: boolean; setAgeConfirmed: (value: boolean) => void; flash: (message: string) => void }) {
  const [notifications, setNotifications] = useState(true);
  const [jurisdiction, setJurisdiction] = useState('California');
  return <OpsPage eyebrow="Account" title="Settings" detail="Your profile, verification, and marketplace preferences." action={<button data-testid="button-save-settings" onClick={() => flash('Settings saved')} className="rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-bold text-[hsl(var(--primary-foreground))]">Save changes</button>}><div className="grid max-w-4xl gap-5 md:grid-cols-[.7fr_1.3fr]"><div><h2 className="font-semibold">Your account</h2><p className="mt-1 text-sm leading-relaxed text-[hsl(var(--muted-foreground))]">Keep your marketplace identity and legal preferences up to date.</p></div><div className="space-y-4"><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-full bg-[hsl(var(--primary))] text-sm font-bold text-[hsl(var(--primary-foreground))]">AM</span><div><p className="font-semibold">Alex Morgan</p><p className="text-xs text-[hsl(var(--muted-foreground))]">alex.morgan@example.com</p></div><button data-testid="button-edit-profile" className="ml-auto rounded-lg p-2 hover:bg-[hsl(var(--muted))]"><Pencil size={15} /></button></div></div><SettingRow icon={ShieldCheck} title="Age verification" detail={ageConfirmed ? 'Verified · 21+ confirmed for this device' : 'Not verified yet'} control={<button data-testid="button-toggle-age-verification" onClick={() => { setAgeConfirmed(!ageConfirmed); flash(ageConfirmed ? 'Age verification removed' : 'Age verified for this device'); }} className={`rounded-full px-3 py-1.5 text-xs font-bold ${ageConfirmed ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}`}>{ageConfirmed ? 'Verified' : 'Verify now'}</button>} /><SettingRow icon={MapPin} title="Shopping jurisdiction" detail="Greenline only shows products available where you shop." control={<select data-testid="select-jurisdiction" aria-label="Shopping jurisdiction" value={jurisdiction} onChange={(e) => setJurisdiction(e.target.value)} className="rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--background))] px-2 py-1.5 text-xs font-bold"><option>California</option><option>Oregon</option><option>Washington</option></select>} /><SettingRow icon={Bell} title="Order updates" detail="Get pickup reminders and seller messages." control={<button data-testid="button-toggle-notifications" aria-pressed={notifications} onClick={() => setNotifications(!notifications)} className={`relative h-6 w-11 rounded-full ${notifications ? 'bg-[hsl(var(--primary))]' : 'bg-[hsl(var(--muted))]'}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-[hsl(var(--card))] transition-transform ${notifications ? 'translate-x-6' : 'translate-x-1'}`} /></button>} /></div></div></OpsPage>;
}
function SettingRow({ icon: Icon, title, detail, control }: { icon: LucideIcon; title: string; detail: string; control: ReactNode }) { return <div className="flex items-center gap-4 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Icon size={18} /></span><div className="min-w-0 flex-1"><p className="font-semibold">{title}</p><p className="mt-1 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]">{detail}</p></div>{control}</div>; }

const queryClient = new QueryClient();
export default App;